"use client"

import * as React from "react"
import {
  CalendarDays,
  Columns3,
  Download,
  GanttChart,
  LayoutGrid,
  List,
  MoreHorizontal,
  Plus,
  Search,
  Table2,
  X,
} from "lucide-react"

import { cn } from "@/lib/utils"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { downloadCsv } from "@/lib/csv"
import {
  draftFromFormData,
  fieldById,
  filterRecords,
  recordTitle,
  recordsToCsv,
  searchRecords,
  sortRecords,
  validateDraft,
  type FieldDef,
  type FilterClause,
  type FilterOp,
  type MultiRecord,
  type SortClause,
  type ViewConfig,
  type ViewKind,
} from "@/lib/multi-view"
import { useMultiView, useOptimisticRecords, type UrlAdapter, type ViewPersistence } from "@/hooks/use-multi-view"
import { EntityForm } from "@/components/ui/entity-form"
import { LayeredPanel, type LayeredPanelMode } from "@/components/ui/layered-panel"
import { RecordProperties } from "@/components/ui/record-properties"
import { ViewCalendar } from "@/components/ui/view-calendar"
import { ViewGallery } from "@/components/ui/view-gallery"
import { ViewGroupedList } from "@/components/ui/view-grouped-list"
import { ViewKanban } from "@/components/ui/view-kanban"
import { useContainerWidth } from "@/components/ui/multi-view-fields"
import { ViewTable } from "@/components/ui/view-table"
import { ViewTimeline } from "@/components/ui/view-timeline"
import { ViewCustomizer, ViewSwitcher as AnimatedViewSwitcher } from "@/components/ui/view-customizer"

const VIEW_ICONS: Record<ViewKind, React.ComponentType<{ className?: string }>> = {
  table: Table2,
  kanban: Columns3,
  calendar: CalendarDays,
  timeline: GanttChart,
  "grouped-list": List,
  gallery: LayoutGrid,
}

export type MultiViewTab = {
  id: string
  label: string
  content: (record: MultiRecord) => React.ReactNode
}

export type MultiViewProps = {
  title: string
  records: readonly MultiRecord[]
  fields: readonly FieldDef[]
  views: readonly ViewConfig[]
  locale?: string
  weekStartsOn?: number
  today?: string
  url?: UrlAdapter | null
  /** Limits the switcher to these view ids. Omit it to keep every view enabled. */
  enabledViews?: readonly string[]
  onEnabledViewsChange?: (ids: string[]) => void
  /** Remembers the enabled set for one project or for every project. */
  persistViews?: ViewPersistence
  /** Shows the animated switcher and the view menu. Also turns on when enabled views are controlled. */
  customizeViews?: boolean
  viewCustomizeTitle?: string
  viewCustomizeSubtitle?: string
  viewCustomizeFooter?: React.ReactNode
  onRecordChange?: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  onCreate?: (draft: Record<string, unknown>) => Promise<void> | void
  onDelete?: (ids: readonly string[]) => Promise<void> | void
  onMove?: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  tabs?: readonly MultiViewTab[]
  bulkActions?: (ids: readonly string[]) => React.ReactNode
  busy?: boolean
  className?: string
  toolbarClassName?: string
  switcherClassName?: string
  searchClassName?: string
  viewClassName?: string
  panelClassName?: string
  addLabel?: string
  searchLabel?: string
  emptyLabel?: string
}

export function MultiView({
  title,
  records,
  fields,
  views,
  locale,
  weekStartsOn = 1,
  today,
  url,
  enabledViews,
  onEnabledViewsChange,
  persistViews,
  customizeViews = false,
  viewCustomizeTitle = "Views",
  viewCustomizeSubtitle,
  viewCustomizeFooter,
  onRecordChange,
  onCreate,
  onDelete,
  onMove,
  tabs = [],
  bulkActions,
  busy = false,
  className,
  toolbarClassName,
  switcherClassName,
  searchClassName,
  viewClassName,
  panelClassName,
  addLabel = "Add",
  searchLabel = "Search",
  emptyLabel = "No records",
}: MultiViewProps) {
  const customizing = customizeViews || enabledViews !== undefined || persistViews !== undefined || onEnabledViewsChange !== undefined
  const state = useMultiView({
    views,
    url,
    enabledViews,
    onEnabledViewsChange,
    persistViews,
  })
  const shownViews = customizing ? views.filter((view) => state.enabledViews.includes(view.id)) : views
  const data = useOptimisticRecords({
    records,
    onRecordChange,
    onCreate,
    onDelete,
    onMove,
  })
  const visible = React.useMemo(() => {
    const searched = searchRecords(data.records, fields, state.query, locale)
    const filtered = filterRecords(searched, fields, state.filters, locale)
    return sortRecords(filtered, fields, state.sort, locale)
  }, [data.records, fields, locale, state.filters, state.query, state.sort])

  const [createOpen, setCreateOpen] = React.useState(false)
  const [createSeed, setCreateSeed] = React.useState<Record<string, unknown>>({})
  const [formError, setFormError] = React.useState<string | null>(null)
  const [confirmDelete, setConfirmDelete] = React.useState(false)
  const [mode, setMode] = React.useState<LayeredPanelMode>("peek")
  const [tab, setTab] = React.useState("details")
  const openRecord = data.records.find((record) => record.id === state.openId) ?? null

  function openCreate(seed: Record<string, unknown> = {}) {
    setCreateSeed(seed)
    setFormError(null)
    setCreateOpen(true)
  }

  function exportCsv(ids: readonly string[]) {
    const rows = ids.length ? visible.filter((record) => ids.includes(record.id)) : visible
    downloadCsv(title.toLowerCase().replace(/\s+/g, "-") || "records", recordsToCsv(rows, fields, locale))
  }

  const count = new Intl.NumberFormat(locale).format(visible.length)
  const selectedCount = state.selectedIds.length

  return (
    <div className={cn("flex min-w-0 flex-col gap-3", className)}>
      {selectedCount > 0 ? (
        <SelectionBar
          count={selectedCount}
          locale={locale}
          className={toolbarClassName}
          views={shownViews}
          viewId={state.viewId}
          onViewChange={state.setViewId}
          onClear={state.clearSelection}
          onExport={() => exportCsv(state.selectedIds)}
          onDelete={() => setConfirmDelete(true)}
          extra={bulkActions?.(state.selectedIds)}
        />
      ) : (
        <Toolbar
          title={title}
          count={count}
          views={shownViews}
          allViews={views}
          enabledViews={state.enabledViews}
          onEnabledViewsChange={state.setEnabledViews}
          customizing={customizing}
          viewCustomizeTitle={viewCustomizeTitle}
          viewCustomizeSubtitle={viewCustomizeSubtitle}
          viewCustomizeFooter={viewCustomizeFooter}
          viewId={state.viewId}
          onViewChange={state.setViewId}
          query={state.query}
          onQueryChange={state.setQuery}
          fields={fields}
          filters={state.filters}
          onFiltersChange={state.setFilters}
          sort={state.sort}
          onSortChange={state.setSort}
          groupBy={state.groupBy}
          onGroupByChange={state.setGroupBy}
          onAdd={() => openCreate()}
          addLabel={addLabel}
          searchLabel={searchLabel}
          className={toolbarClassName}
          switcherClassName={switcherClassName}
          searchClassName={searchClassName}
        />
      )}
      <div className={cn("min-w-0", viewClassName)}>
        <ActiveView
          view={state.active}
          records={visible}
          fields={fields}
          locale={locale}
          weekStartsOn={weekStartsOn}
          today={today}
          groupBy={state.groupBy}
          sort={state.sort}
          onSortChange={state.setSort}
          selectedIds={state.selectedIds}
          onSelectedIdsChange={state.setSelectedIds}
          onOpen={(id) => {
            setMode("peek")
            setTab("details")
            state.setOpenId(id)
          }}
          onDelete={(ids) => data.remove(ids)}
          onMove={(id, patch) => data.move(id, patch)}
          onCreateRequest={openCreate}
          emptyLabel={emptyLabel}
        />
      </div>
      <LayeredPanel
        open={Boolean(openRecord)}
        onOpenChange={(open) => {
          if (!open) state.setOpenId(null)
        }}
        mode={mode}
        onModeChange={setMode}
        title={openRecord ? recordTitle(openRecord, fields, state.active?.titleField) : title}
        className={panelClassName}
      >
        <LayeredPanel.Header>
          {openRecord ? (
            <TitleEditor
              record={openRecord}
              fields={fields}
              titleField={state.active?.titleField}
              onCommit={(patch) => data.update(openRecord.id, patch)}
            />
          ) : null}
        </LayeredPanel.Header>
        <LayeredPanel.ExpandToggle expandLabel="Expand record" collapseLabel="Collapse record" />
        <LayeredPanel.Peek>
          {openRecord && mode === "peek" ? (
            <RecordBody
              record={openRecord}
              fields={fields}
              locale={locale}
              tab={tab}
              tabs={tabs}
              onTabChange={setTab}
              onChange={(id, patch) => data.update(id, patch)}
            />
          ) : openRecord ? (
            <p className="truncate text-sm text-muted-foreground" dir="auto">
              {recordTitle(openRecord, fields, state.active?.titleField)}
            </p>
          ) : null}
        </LayeredPanel.Peek>
        <LayeredPanel.Full>
          {openRecord && mode === "full" ? (
            <RecordBody
              record={openRecord}
              fields={fields}
              locale={locale}
              tab={tab}
              tabs={tabs}
              onTabChange={setTab}
              onChange={(id, patch) => data.update(id, patch)}
            />
          ) : null}
        </LayeredPanel.Full>
      </LayeredPanel>
      <EntityForm
        open={createOpen}
        onOpenChange={setCreateOpen}
        title={addLabel}
        description={formError ?? undefined}
        busy={busy}
        onSubmit={async (formData) => {
          const draft = { ...createSeed, ...draftFromFormData(formData, fields) }
          const error = validateDraft(draft, fields, state.active?.titleField)
          if (error) {
            setFormError(error)
            throw new Error(error)
          }
          setFormError(null)
          await data.create(draft)
        }}
      >
        <CreateFields fields={fields} seed={createSeed} />
      </EntityForm>
      <AlertDialog open={confirmDelete} onOpenChange={setConfirmDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete records</AlertDialogTitle>
            <AlertDialogDescription>
              Delete {selectedCount} selected {selectedCount === 1 ? "record" : "records"}?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={() => {
                const ids = state.selectedIds
                state.clearSelection()
                void data.remove(ids)
              }}
            >
              Delete records
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

function RecordBody({
  record,
  fields,
  locale,
  tab,
  tabs,
  onTabChange,
  onChange,
}: {
  record: MultiRecord
  fields: readonly FieldDef[]
  locale?: string
  tab: string
  tabs: readonly MultiViewTab[]
  onTabChange: (tab: string) => void
  onChange: (id: string, patch: Record<string, unknown>) => Promise<void> | void
}) {
  const active = tabs.find((item) => item.id === tab)
  return (
    <div className="flex flex-col gap-3">
      <Tabs value={tab} onValueChange={onTabChange}>
        <TabsList>
          <TabsTrigger value="details">Details</TabsTrigger>
          {tabs.map((item) => (
            <TabsTrigger key={item.id} value={item.id}>
              {item.label}
            </TabsTrigger>
          ))}
        </TabsList>
      </Tabs>
      {tab === "details" || !active ? (
        <RecordProperties record={record} fields={fields} locale={locale} onChange={onChange} />
      ) : (
        active.content(record)
      )}
    </div>
  )
}

function TitleEditor({
  record,
  fields,
  titleField,
  onCommit,
}: {
  record: MultiRecord
  fields: readonly FieldDef[]
  titleField?: string
  onCommit: (patch: Record<string, unknown>) => Promise<void> | void
}) {
  const field = fields.find((item) => item.id === titleField) ?? fields.find((item) => item.type === "text")
  const current = field ? String(record[field.id] ?? "") : recordTitle(record, fields, titleField)
  const [value, setValue] = React.useState(current)
  const [seen, setSeen] = React.useState(current)
  if (seen !== current) {
    setSeen(current)
    setValue(current)
  }
  if (!field || field.readOnly) {
    return <h2 className="truncate text-lg font-semibold" dir="auto">{current}</h2>
  }
  return (
    <input
      aria-label={field.label}
      value={value}
      dir="auto"
      onChange={(event) => setValue(event.target.value)}
      onBlur={() => {
        if (value !== current) void onCommit({ [field.id]: value })
      }}
      onKeyDown={(event) => {
        if (event.key === "Enter") {
          event.preventDefault()
          void onCommit({ [field.id]: value })
        }
        if (event.key === "Escape") {
          setValue(current)
          event.currentTarget.blur()
        }
      }}
      className="w-full truncate bg-transparent text-lg font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring"
    />
  )
}

function SelectionBar({
  count,
  locale,
  className,
  views,
  viewId,
  onViewChange,
  onClear,
  onExport,
  onDelete,
  extra,
}: {
  count: number
  locale?: string
  className?: string
  views: readonly ViewConfig[]
  viewId: string
  onViewChange: (id: string) => void
  onClear: () => void
  onExport: () => void
  onDelete: () => void
  extra?: React.ReactNode
}) {
  const label = new Intl.NumberFormat(locale).format(count)
  return (
    <div className={cn("flex min-w-0 flex-wrap items-center gap-2 rounded-lg border border-border bg-muted px-3 py-2", className)}>
      <p className="text-sm font-medium">{label} selected</p>
      <ViewSwitcher views={views} viewId={viewId} mode="icons" onViewChange={onViewChange} />
      <Button type="button" variant="ghost" size="sm" onClick={onClear}>
        <X className="size-3.5" />
        Clear
      </Button>
      <div className="ml-auto flex flex-wrap items-center gap-2">
        {extra}
        <Button type="button" variant="outline" size="sm" onClick={onExport}>
          <Download className="size-3.5" />
          Export CSV
        </Button>
        <Button type="button" variant="destructive" size="sm" onClick={onDelete}>
          Delete
        </Button>
      </div>
    </div>
  )
}

function Toolbar({
  title,
  count,
  views,
  allViews,
  enabledViews,
  onEnabledViewsChange,
  customizing = false,
  viewCustomizeTitle,
  viewCustomizeSubtitle,
  viewCustomizeFooter,
  viewId,
  onViewChange,
  query,
  onQueryChange,
  fields,
  filters,
  onFiltersChange,
  sort,
  onSortChange,
  groupBy,
  onGroupByChange,
  onAdd,
  addLabel,
  searchLabel,
  className,
  switcherClassName,
  searchClassName,
}: {
  title: string
  count: string
  views: readonly ViewConfig[]
  allViews: readonly ViewConfig[]
  enabledViews: readonly string[]
  onEnabledViewsChange: (ids: string[]) => void
  customizing?: boolean
  viewCustomizeTitle: string
  viewCustomizeSubtitle?: string
  viewCustomizeFooter?: React.ReactNode
  viewId: string
  onViewChange: (id: string) => void
  query: string
  onQueryChange: (query: string) => void
  fields: readonly FieldDef[]
  filters: readonly FilterClause[]
  onFiltersChange: (filters: FilterClause[]) => void
  sort: SortClause | null
  onSortChange: (sort: SortClause | null) => void
  groupBy: string | null
  onGroupByChange: (groupBy: string | null) => void
  onAdd: () => void
  addLabel: string
  searchLabel: string
  className?: string
  switcherClassName?: string
  searchClassName?: string
}) {
  const [ref, width] = useContainerWidth<HTMLDivElement>()
  const mode = width > 0 && width < 360 ? "select" : width > 0 && width < 640 ? "icons" : "labels"
  const groupable = fields.filter((field) =>
    field.type === "select" || field.type === "status" || field.type === "person" || field.type === "relation",
  )
  return (
    <div ref={ref} className={cn("flex min-w-0 flex-wrap items-center gap-2", className)}>
      <div className="min-w-0">
        <h2 className="truncate text-base font-semibold">{title}</h2>
        <p className="text-xs text-muted-foreground">{count}</p>
      </div>
      {customizing ? (
        <AnimatedViewSwitcher
          className={switcherClassName}
          views={views.map((view) => {
            const Icon = VIEW_ICONS[view.kind]
            return { id: view.id, label: view.label, icon: <Icon className="size-3.5" /> }
          })}
          value={viewId}
          onValueChange={onViewChange}
          menu={
            <ViewCustomizer
              title={viewCustomizeTitle}
              subtitle={viewCustomizeSubtitle}
              footer={viewCustomizeFooter}
              views={allViews.map((view) => {
                const Icon = VIEW_ICONS[view.kind]
                return { id: view.id, label: view.label, icon: <Icon className="size-3.5" /> }
              })}
              enabled={enabledViews}
              onEnabledChange={onEnabledViewsChange}
            >
              <Button type="button" variant="outline" size="icon-sm" className="rounded-full" aria-label={viewCustomizeTitle}>
                <MoreHorizontal />
              </Button>
            </ViewCustomizer>
          }
        />
      ) : (
        <ViewSwitcher
          views={views}
          viewId={viewId}
          mode={mode}
          onViewChange={onViewChange}
          className={switcherClassName}
        />
      )}
      <div className={cn("relative min-w-0 flex-1 basis-36", searchClassName)}>
        <Search className="pointer-events-none absolute top-1/2 left-2 size-3.5 -translate-y-1/2 text-muted-foreground" />
        <Input
          value={query}
          onChange={(event) => onQueryChange(event.target.value)}
          placeholder={searchLabel}
          aria-label={searchLabel}
          className="pl-7"
        />
      </div>
      <FilterMenu fields={fields} filters={filters} onChange={onFiltersChange} />
      <SortMenu fields={fields} sort={sort} onChange={onSortChange} />
      <GroupMenu fields={groupable} groupBy={groupBy} onChange={onGroupByChange} />
      <Button type="button" size="sm" onClick={onAdd}>
        <Plus className="size-3.5" />
        {addLabel}
      </Button>
    </div>
  )
}

function ViewSwitcher({
  views,
  viewId,
  mode,
  onViewChange,
  className,
}: {
  views: readonly ViewConfig[]
  viewId: string
  mode: "select" | "icons" | "labels"
  onViewChange: (id: string) => void
  className?: string
}) {
  if (mode === "select") {
    return (
      <select
        aria-label="View"
        className={cn("h-8 rounded-md border border-input bg-background px-2 text-sm", className)}
        value={viewId}
        onChange={(event) => onViewChange(event.target.value)}
      >
        {views.map((view) => (
          <option key={view.id} value={view.id}>
            {view.label}
          </option>
        ))}
      </select>
    )
  }
  return (
    <div role="radiogroup" aria-label="View" className={cn("flex rounded-lg border border-border p-0.5", className)}>
      {views.map((view) => {
        const Icon = VIEW_ICONS[view.kind]
        const active = view.id === viewId
        return (
          <button
            key={view.id}
            type="button"
            role="radio"
            aria-checked={active}
            className={cn(
              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs focus-visible:ring-2 focus-visible:ring-ring",
              active ? "bg-muted text-foreground" : "text-muted-foreground",
            )}
            onClick={() => onViewChange(view.id)}
          >
            <Icon className="size-3.5" />
            <span className={mode === "icons" ? "sr-only" : undefined}>{view.label}</span>
          </button>
        )
      })}
    </div>
  )
}

const OPS: { op: FilterOp; label: string }[] = [
  { op: "contains", label: "contains" },
  { op: "is", label: "is" },
  { op: "isNot", label: "is not" },
  { op: "gt", label: "greater than" },
  { op: "lt", label: "less than" },
  { op: "before", label: "before" },
  { op: "after", label: "after" },
  { op: "empty", label: "is empty" },
  { op: "notEmpty", label: "is not empty" },
]

function FilterMenu({
  fields,
  filters,
  onChange,
}: {
  fields: readonly FieldDef[]
  filters: readonly FilterClause[]
  onChange: (filters: FilterClause[]) => void
}) {
  const [field, setField] = React.useState(fields[0]?.id ?? "")
  const [op, setOp] = React.useState<FilterOp>("contains")
  const [value, setValue] = React.useState("")
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button type="button" variant="outline" size="sm">
          Filter{filters.length ? ` (${filters.length})` : ""}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent className="w-72" align="end">
        <DropdownMenuLabel>Filter</DropdownMenuLabel>
        {filters.map((clause) => (
          <DropdownMenuItem
            key={clause.id}
            onSelect={() => onChange(filters.filter((item) => item.id !== clause.id))}
          >
            {fieldById(fields, clause.field)?.label ?? clause.field} {clause.op} {clause.value}
          </DropdownMenuItem>
        ))}
        <DropdownMenuSeparator />
        <div className="grid gap-2 p-2" onKeyDown={(event) => event.stopPropagation()}>
          <select className="h-8 rounded-md border border-input bg-background px-2 text-sm" value={field} onChange={(event) => setField(event.target.value)} aria-label="Filter field">
            {fields.map((item) => (
              <option key={item.id} value={item.id}>{item.label}</option>
            ))}
          </select>
          <select className="h-8 rounded-md border border-input bg-background px-2 text-sm" value={op} onChange={(event) => setOp(event.target.value as FilterOp)} aria-label="Filter operator">
            {OPS.map((item) => (
              <option key={item.op} value={item.op}>{item.label}</option>
            ))}
          </select>
          <Input aria-label="Filter value" value={value} onChange={(event) => setValue(event.target.value)} />
          <Button
            type="button"
            size="sm"
            onClick={() => {
              if (!field) return
              onChange([...filters, { id: `f_${filters.length}_${field}`, field, op, value }])
              setValue("")
            }}
          >
            Add filter
          </Button>
        </div>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function SortMenu({
  fields,
  sort,
  onChange,
}: {
  fields: readonly FieldDef[]
  sort: SortClause | null
  onChange: (sort: SortClause | null) => void
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button type="button" variant="outline" size="sm">Sort</Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem onSelect={() => onChange(null)}>None</DropdownMenuItem>
        {fields.map((field) => (
          <DropdownMenuItem
            key={field.id}
            onSelect={() =>
              onChange({
                field: field.id,
                direction: sort?.field === field.id && sort.direction === "asc" ? "desc" : "asc",
              })
            }
          >
            {field.label}
            {sort?.field === field.id ? ` (${sort.direction})` : ""}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function GroupMenu({
  fields,
  groupBy,
  onChange,
}: {
  fields: readonly FieldDef[]
  groupBy: string | null
  onChange: (groupBy: string | null) => void
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button type="button" variant="outline" size="sm">Group</Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem onSelect={() => onChange(null)}>None</DropdownMenuItem>
        {fields.map((field) => (
          <DropdownMenuItem key={field.id} onSelect={() => onChange(field.id)}>
            {field.label}
            {groupBy === field.id ? " ✓" : ""}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function CreateFields({
  fields,
  seed,
}: {
  fields: readonly FieldDef[]
  seed: Record<string, unknown>
}) {
  return (
    <>
      {fields.filter((field) => !field.readOnly).map((field) => (
        <label key={field.id} className="grid gap-1 text-sm">
          <span className="text-muted-foreground">{field.label}</span>
          {field.type === "select" || field.type === "status" ? (
            <select
              name={field.id}
              defaultValue={typeof seed[field.id] === "string" ? String(seed[field.id]) : ""}
              className="h-9 rounded-md border border-input bg-background px-2"
            >
              <option value="">Select</option>
              {(field.options ?? []).map((option) => (
                <option key={option.value} value={option.value}>{option.label}</option>
              ))}
            </select>
          ) : field.type === "boolean" ? (
            <input type="checkbox" name={field.id} value="true" defaultChecked={seed[field.id] === true} />
          ) : field.type === "date" ? (
            <input type="date" name={field.id} defaultValue={typeof seed[field.id] === "string" ? String(seed[field.id]) : ""} className="h-9 rounded-md border border-input bg-background px-2" />
          ) : field.type === "daterange" ? (
            <span className="flex gap-2">
              <input type="date" name={field.id} className="h-9 flex-1 rounded-md border border-input bg-background px-2" />
              <input type="date" name={`${field.id}__end`} className="h-9 flex-1 rounded-md border border-input bg-background px-2" />
            </span>
          ) : (
            <Input
              name={field.id}
              type={field.type === "number" || field.type === "currency" || field.type === "progress" ? "number" : "text"}
              defaultValue={seed[field.id] == null ? "" : String(seed[field.id])}
            />
          )}
        </label>
      ))}
    </>
  )
}

function ActiveView({
  view,
  records,
  fields,
  locale,
  weekStartsOn,
  today,
  groupBy,
  sort,
  onSortChange,
  selectedIds,
  onSelectedIdsChange,
  onOpen,
  onDelete,
  onMove,
  onCreateRequest,
  emptyLabel,
}: {
  view: ViewConfig | undefined
  records: readonly MultiRecord[]
  fields: readonly FieldDef[]
  locale?: string
  weekStartsOn: number
  today?: string
  groupBy: string | null
  sort: SortClause | null
  onSortChange: (sort: SortClause | null) => void
  selectedIds: readonly string[]
  onSelectedIdsChange: (ids: string[]) => void
  onOpen: (id: string) => void
  onDelete: (ids: readonly string[]) => Promise<void> | void
  onMove: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  onCreateRequest: (seed: Record<string, unknown>) => void
  emptyLabel: string
}) {
  if (!view) return null
  const config = { ...view, groupField: groupBy ?? undefined }
  if (view.kind === "table") {
    return (
      <ViewTable
        records={records}
        fields={fields}
        config={config}
        locale={locale}
        sort={sort}
        onSortChange={onSortChange}
        selectedIds={selectedIds}
        onSelectedIdsChange={onSelectedIdsChange}
        onOpen={onOpen}
        onDelete={onDelete}
        emptyLabel={emptyLabel}
      />
    )
  }
  if (view.kind === "kanban") {
    return (
      <ViewKanban
        records={records}
        fields={fields}
        config={config}
        locale={locale}
        selectedIds={selectedIds}
        onSelectedIdsChange={onSelectedIdsChange}
        onOpen={onOpen}
        onDelete={onDelete}
        onMove={onMove}
        onCreateRequest={onCreateRequest}
        emptyLabel={emptyLabel}
      />
    )
  }
  if (view.kind === "calendar") {
    return (
      <ViewCalendar
        records={records}
        fields={fields}
        config={config}
        locale={locale}
        weekStartsOn={weekStartsOn}
        today={today}
        onOpen={onOpen}
        onMove={onMove}
      />
    )
  }
  if (view.kind === "timeline") {
    return (
      <ViewTimeline
        records={records}
        fields={fields}
        config={config}
        locale={locale}
        weekStartsOn={weekStartsOn}
        today={today}
        onOpen={onOpen}
        onMove={onMove}
      />
    )
  }
  if (view.kind === "grouped-list") {
    return (
      <ViewGroupedList
        records={records}
        fields={fields}
        config={config}
        locale={locale}
        onOpen={onOpen}
        emptyLabel={emptyLabel}
      />
    )
  }
  return (
    <ViewGallery
      records={records}
      fields={fields}
      config={config}
      locale={locale}
      onOpen={onOpen}
      emptyLabel={emptyLabel}
    />
  )
}

"use client"

import * as React from "react"
import {
  createColumnHelper,
  tableFeatures,
  useTable,
  columnVisibilityFeature,
  rowSelectionFeature,
} from "@tanstack/react-table"
import { ArrowDown, ArrowUp, ChevronsUpDown, MoreHorizontal, SlidersHorizontal } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  fieldById,
  recordTitle,
  type FieldDef,
  type MultiRecord,
  type SortClause,
  type ViewConfig,
} from "@/lib/multi-view"
import { FieldDisplay, FieldIcon } from "@/components/ui/multi-view-fields"

const features = tableFeatures({
  rowSelectionFeature,
  columnVisibilityFeature,
})

type Row = MultiRecord
const helper = createColumnHelper<typeof features, Row>()

export type ViewTableProps = {
  records: readonly MultiRecord[]
  fields: readonly FieldDef[]
  config?: ViewConfig
  locale?: string
  sort?: SortClause | null
  onSortChange?: (sort: SortClause | null) => void
  selectedIds?: readonly string[]
  onSelectedIdsChange?: (ids: string[]) => void
  onOpen?: (id: string) => void
  onDelete?: (ids: readonly string[]) => Promise<void> | void
  emptyLabel?: string
  openLabel?: string
  columnsLabel?: string
  className?: string
  toolbarClassName?: string
  tableClassName?: string
  rowClassName?: string
  headerClassName?: string
}

export function ViewTable({
  records,
  fields,
  config,
  locale,
  sort = null,
  onSortChange,
  selectedIds,
  onSelectedIdsChange,
  onOpen,
  onDelete,
  emptyLabel = "No records",
  openLabel = "Open",
  columnsLabel = "Columns",
  className,
  toolbarClassName,
  tableClassName,
  rowClassName,
  headerClassName,
}: ViewTableProps) {
  const [innerSelected, setInnerSelected] = React.useState<string[]>([])
  const selected = selectedIds ?? innerSelected
  const setSelected = React.useCallback(
    (ids: string[]) => {
      if (selectedIds === undefined) setInnerSelected(ids)
      onSelectedIdsChange?.(ids)
    },
    [onSelectedIdsChange, selectedIds],
  )

  const titleId = config?.titleField
  const columnFields = React.useMemo(() => {
    const ids = config?.columns
    const list = ids?.length
      ? ids.flatMap((id) => {
          const field = fieldById(fields, id)
          return field ? [field] : []
        })
      : [...fields]
    return list
  }, [config?.columns, fields])

  const data = React.useMemo(() => records as Row[], [records])

  const rowSelection = React.useMemo(() => {
    const next: Record<string, true> = {}
    for (const id of selected) next[id] = true
    return next
  }, [selected])

  const columns = React.useMemo(
    () =>
      helper.columns([
        helper.display({
          id: "select",
          enableHiding: false,
          header: ({ table }) => (
            <Checkbox
              aria-label="Select all"
              checked={
                table.getIsAllRowsSelected()
                  ? true
                  : table.getIsSomeRowsSelected()
                    ? "indeterminate"
                    : false
              }
              onCheckedChange={(value) => table.toggleAllRowsSelected(value === true)}
            />
          ),
          cell: ({ row }) => (
            <Checkbox
              aria-label={`Select ${recordTitle(row.original, fields, titleId)}`}
              checked={row.getIsSelected()}
              onCheckedChange={(value) => row.toggleSelected(value === true)}
            />
          ),
        }),
        ...columnFields.map((field) =>
          helper.display({
            id: field.id,
            header: () => field.label,
            cell: ({ row }) => (
              <FieldCell
                field={field}
                record={row.original}
                locale={locale}
                title={field.id === (titleId ?? columnFields.find((item) => item.type === "text")?.id)}
                openLabel={openLabel}
                onOpen={onOpen}
              />
            ),
          }),
        ),
        helper.display({
          id: "actions",
          enableHiding: false,
          header: () => <span className="sr-only">Actions</span>,
          cell: ({ row }) => (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="size-7"
                  aria-label={`Actions for ${recordTitle(row.original, fields, titleId)}`}
                >
                  <MoreHorizontal className="size-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem onSelect={() => onOpen?.(row.original.id)}>{openLabel}</DropdownMenuItem>
                {onDelete ? (
                  <DropdownMenuItem onSelect={() => void onDelete([row.original.id])}>Delete</DropdownMenuItem>
                ) : null}
              </DropdownMenuContent>
            </DropdownMenu>
          ),
        }),
      ]),
    [columnFields, fields, locale, onDelete, onOpen, openLabel, titleId],
  )

  const table = useTable({
    features,
    data,
    columns,
    getRowId: (row) => row.id,
    state: { rowSelection },
    onRowSelectionChange: (updater) => {
      const next = typeof updater === "function" ? updater(rowSelection) : updater
      setSelected(Object.keys(next).filter((id) => next[id] === true))
    },
  })

  const titleField = titleId ?? columnFields.find((field) => field.type === "text")?.id

  return (
    <div className={cn("flex min-w-0 flex-col gap-2", className)}>
      <div className={cn("flex justify-end", toolbarClassName)}>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button type="button" variant="outline" size="sm">
              <SlidersHorizontal className="size-3.5" />
              {columnsLabel}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {table.getAllLeafColumns().map((column) =>
              column.getCanHide() ? (
                <DropdownMenuCheckboxItem
                  key={column.id}
                  checked={column.getIsVisible()}
                  onCheckedChange={(value) => column.toggleVisibility(value === true)}
                >
                  {fieldById(fields, column.id)?.label ?? column.id}
                </DropdownMenuCheckboxItem>
              ) : null,
            )}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
      <div className="min-w-0 overflow-auto">
        <Table className={tableClassName}>
          <TableHeader className={headerClassName}>
            {table.getHeaderGroups().map((group) => (
              <TableRow key={group.id}>
                {group.headers.map((header) => {
                  const field = fieldById(fields, header.column.id)
                  const sortable = Boolean(field && onSortChange)
                  const active = sort?.field === header.column.id
                  return (
                    <TableHead key={header.id} aria-sort={ariaSort(active ? sort : null, header.column.id)}>
                      {header.isPlaceholder ? null : field && sortable ? (
                        <button
                          type="button"
                          className="inline-flex items-center gap-1 rounded-sm text-left font-medium focus-visible:ring-2 focus-visible:ring-ring"
                          onClick={() => onSortChange?.(nextSort(sort, field.id))}
                        >
                          <FieldIcon name={field.icon} className="size-3.5 text-muted-foreground" />
                          <span>{field.label}</span>
                          {active && sort?.direction === "asc" ? (
                            <ArrowUp className="size-3.5" aria-hidden />
                          ) : active && sort?.direction === "desc" ? (
                            <ArrowDown className="size-3.5" aria-hidden />
                          ) : (
                            <ChevronsUpDown className="size-3.5 text-muted-foreground" aria-hidden />
                          )}
                        </button>
                      ) : (
                        <table.FlexRender header={header} />
                      )}
                    </TableHead>
                  )
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length === 0 ? (
              <TableRow>
                <TableCell colSpan={table.getVisibleLeafColumns().length} className="h-24 text-center text-muted-foreground">
                  {emptyLabel}
                </TableCell>
              </TableRow>
            ) : (
              table.getRowModel().rows.map((row) => (
                <TableRow key={row.id} data-state={row.getIsSelected() ? "selected" : undefined} className={rowClassName}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className="max-w-64">
                      {cell.column.id === titleField || cell.column.id === "select" || cell.column.id === "actions" ? (
                        <table.FlexRender cell={cell} />
                      ) : (
                        <table.FlexRender cell={cell} />
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

function ariaSort(sort: SortClause | null, id: string): "ascending" | "descending" | "none" | undefined {
  if (!sort || sort.field !== id) return undefined
  return sort.direction === "asc" ? "ascending" : "descending"
}

function nextSort(sort: SortClause | null, field: string): SortClause | null {
  if (sort?.field !== field) return { field, direction: "asc" }
  if (sort.direction === "asc") return { field, direction: "desc" }
  return null
}

function FieldCell({
  field,
  record,
  locale,
  title,
  openLabel,
  onOpen,
}: {
  field: FieldDef
  record: MultiRecord
  locale?: string
  title: boolean
  openLabel: string
  onOpen?: (id: string) => void
}) {
  if (!title) return <FieldDisplay field={field} value={record[field.id]} locale={locale} />
  const label = recordTitle(record, [field], field.id)
  return (
    <span className="group flex min-w-0 items-center gap-2">
      <span className="grid size-6 shrink-0 place-items-center rounded-md bg-muted text-[10px] font-medium">
        {label.slice(0, 1).toUpperCase()}
      </span>
      <button
        type="button"
        className="min-w-0 truncate rounded-sm text-left font-medium focus-visible:ring-2 focus-visible:ring-ring"
        dir="auto"
        onClick={() => onOpen?.(record.id)}
      >
        {label}
      </button>
      <span className="text-xs text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100 group-focus-within:opacity-100 motion-reduce:transition-none">
        {openLabel}
      </span>
    </span>
  )
}

"use client"

import * as React from "react"
import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  closestCorners,
  useDroppable,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragStartEvent,
} from "@dnd-kit/core"
import {
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable"
import { CSS } from "@dnd-kit/utilities"
import { GripVertical, MoreHorizontal, Plus } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  fieldById,
  formatCurrency,
  formatNumber,
  groupRecordsWithSum,
  recordTitle,
  type FieldDef,
  type MultiRecord,
  type ViewConfig,
} from "@/lib/multi-view"
import { PriorityBadge, PRIORITY_LEVELS, type PriorityLevel } from "@/components/ui/priority-badge"
import {
  FieldDisplay,
  FieldIcon,
  StatusPill,
  displayFields,
  usePrefersReducedMotion,
} from "@/components/ui/multi-view-fields"

export type ViewKanbanProps = {
  records: readonly MultiRecord[]
  fields: readonly FieldDef[]
  config: ViewConfig
  locale?: string
  selectedIds?: readonly string[]
  onSelectedIdsChange?: (ids: string[]) => void
  onOpen?: (id: string) => void
  onDelete?: (ids: readonly string[]) => Promise<void> | void
  onMove?: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  onCreateRequest?: (seed: Record<string, unknown>) => void
  emptyLabel?: string
  emptyHint?: string
  addLabel?: string
  moveLabel?: string
  /** Collapse a column after this many cards and offer the rest behind a button. */
  maxVisible?: number
  moreLabel?: (hidden: number) => string
  /** Cards that should wear a highlight ring for a short time. */
  highlightedIds?: readonly string[]
  /** Summary cards read priority, due, amount, and progress when those keys exist. */
  cardLayout?: "fields" | "summary"
  className?: string
  columnClassName?: string
  cardClassName?: string
}

export function ViewKanban({
  records,
  fields,
  config,
  locale,
  selectedIds = [],
  onSelectedIdsChange,
  onOpen,
  onDelete,
  onMove,
  onCreateRequest,
  emptyLabel = "No items",
  emptyHint,
  addLabel = "Add item",
  moveLabel = "Move to…",
  maxVisible,
  moreLabel = (hidden) => `${hidden} more`,
  highlightedIds,
  cardLayout = "fields",
  className,
  columnClassName,
  cardClassName,
}: ViewKanbanProps) {
  const reduced = usePrefersReducedMotion()
  const groupField = fieldById(fields, config.groupField)
  const sum = fieldById(fields, config.sumField)
  const groups = React.useMemo(
    () =>
      groupRecordsWithSum(records, fields, config.groupField, config.sumField, {
        includeEmpty: true,
        locale,
      }),
    [config.groupField, config.sumField, fields, locale, records],
  )
  const titleFields = fields
  const cardFields = displayFields(
    fields,
    config.cardFields,
    new Set([config.titleField, config.groupField].filter((id): id is string => Boolean(id))),
  ).slice(0, 3)

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )
  const [activeId, setActiveId] = React.useState<string | null>(null)
  const [expanded, setExpanded] = React.useState<Record<string, boolean>>({})
  const active = records.find((record) => record.id === activeId) ?? null

  function labelFor(id: string) {
    if (id.startsWith("col:")) {
      const key = id.slice(4)
      return groups.find((group) => group.key === key)?.label ?? key
    }
    const record = records.find((item) => item.id === id)
    return record ? recordTitle(record, titleFields, config.titleField) : id
  }

  function onDragStart(event: DragStartEvent) {
    setActiveId(String(event.active.id))
  }

  function onDragEnd(event: DragEndEvent) {
    setActiveId(null)
    const id = String(event.active.id)
    const overId = event.over ? String(event.over.id) : ""
    if (!overId || !groupField) return
    const nextKey = overId.startsWith("col:")
      ? overId.slice(4)
      : groupKeyOf(records.find((record) => record.id === overId), groupField.id)
    const current = records.find((record) => record.id === id)
    if (!current || nextKey == null) return
    if (String(current[groupField.id] ?? "") === nextKey) return
    void onMove?.(id, { [groupField.id]: nextKey })
  }

  function moveTo(id: string, key: string) {
    if (!groupField) return
    void onMove?.(id, { [groupField.id]: key })
  }

  function toggle(id: string, checked: boolean) {
    if (!onSelectedIdsChange) return
    const next = checked ? [...selectedIds, id] : selectedIds.filter((item) => item !== id)
    onSelectedIdsChange(next)
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCorners}
      onDragStart={onDragStart}
      onDragEnd={onDragEnd}
      onDragCancel={() => setActiveId(null)}
      accessibility={{
        announcements: {
          onDragStart({ active: item }) {
            return `Picked up ${labelFor(String(item.id))}.`
          },
          onDragOver({ over }) {
            return over ? `Over ${labelFor(String(over.id))}.` : ""
          },
          onDragEnd({ over }) {
            return over ? `Moved to ${labelFor(String(over.id))}.` : "Dropped."
          },
          onDragCancel() {
            return "Cancelled."
          },
        },
      }}
    >
      <div
        data-reduced-motion={reduced ? "true" : "false"}
        className={cn(
          "flex min-w-0 snap-x snap-mandatory gap-3 overflow-x-auto pb-2",
          className,
        )}
      >
        {groups.map((group) => (
          <Column
            key={group.key || "empty"}
            id={`col:${group.key}`}
            className={columnClassName}
          >
            <header className="flex items-center gap-2">
              {groupField ? (
                <StatusPill field={groupField} value={group.key || null} />
              ) : (
                <span className="text-sm font-medium">{group.label}</span>
              )}
              <span className="rounded-full bg-background px-2 py-0.5 text-xs tabular-nums text-muted-foreground">{group.records.length}</span>
              {group.sum != null && sum ? (
                <span className="ml-auto text-xs text-muted-foreground">
                  {sum.type === "currency"
                    ? formatCurrency(group.sum, locale, sum.currency, sum.format ?? "compact")
                    : formatNumber(group.sum, locale)}
                </span>
              ) : null}
            </header>
            <SortableContext items={group.records.map((record) => record.id)} strategy={verticalListSortingStrategy}>
              <div className="flex min-h-24 flex-col gap-2">
                {group.records.length === 0 ? (
                  <div className="flex flex-col items-center gap-2 rounded-lg border border-dashed border-border px-3 py-6 text-center">
                    <div className="flex items-end gap-1" aria-hidden>
                      <span className="h-5 w-7 rounded-md bg-muted" />
                      <span className="h-8 w-7 rounded-md bg-muted" />
                      <span className="h-6 w-7 rounded-md bg-background" />
                    </div>
                    <p className="text-sm font-medium">{emptyLabel}</p>
                    {emptyHint ? <p className="text-xs text-muted-foreground">{emptyHint}</p> : null}
                  </div>
                ) : (
                  (maxVisible != null && !expanded[group.key] ? group.records.slice(0, maxVisible) : group.records).map((record) => (
                    <Card
                      key={record.id}
                      record={record}
                      fields={fields}
                      titleField={config.titleField}
                      cardFields={cardFields}
                      locale={locale}
                      groupKey={group.key}
                      selected={selectedIds.includes(record.id)}
                      onSelectedChange={(checked) => toggle(record.id, checked)}
                      onOpen={onOpen}
                      onDelete={onDelete}
                      reduced={reduced}
                      className={cardClassName}
                      moveLabel={moveLabel}
                      groups={groups.map((item) => ({ key: item.key, label: item.label }))}
                      onMoveTo={(key) => moveTo(record.id, key)}
                      highlighted={highlightedIds?.includes(record.id)}
                      layout={cardLayout}
                    />
                  ))
                )}
              </div>
            </SortableContext>
            {maxVisible != null && !expanded[group.key] && group.records.length > maxVisible ? (
              <Button type="button" variant="ghost" size="sm" className="justify-start" onClick={() => setExpanded((current) => ({ ...current, [group.key]: true }))}>
                {moreLabel(group.records.length - maxVisible)}
              </Button>
            ) : null}
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="justify-start"
              onClick={() => onCreateRequest?.(groupField ? { [groupField.id]: group.key } : {})}
            >
              <Plus className="size-3.5" />
              {addLabel}
            </Button>
          </Column>
        ))}
      </div>
      <DragOverlay dropAnimation={reduced ? null : undefined}>
        {active ? (
          <article className="rounded-lg border border-border bg-card p-3 shadow-md">
            <p className="truncate text-sm font-medium" dir="auto">
              {recordTitle(active, fields, config.titleField)}
            </p>
          </article>
        ) : null}
      </DragOverlay>
    </DndContext>
  )
}

function isPriority(value: unknown): value is PriorityLevel {
  return typeof value === "string" && (PRIORITY_LEVELS as readonly string[]).includes(value)
}

function SummaryChips({ record }: { record: MultiRecord }) {
  const priority = isPriority(record.priority) ? record.priority : null
  const due = typeof record.due === "string" ? record.due : null
  const amount = typeof record.amount === "string" || typeof record.amount === "number" ? String(record.amount) : null
  const subtitle = typeof record.subtitle === "string" ? record.subtitle : null
  const progress =
    record.progress && typeof record.progress === "object"
      ? (record.progress as { done?: number; total?: number })
      : null
  return (
    <div className="mt-2 flex flex-col gap-2">
      <div className="flex flex-wrap gap-1">
        {priority ? <PriorityBadge level={priority} /> : null}
        {due ? <span className="inline-flex h-6 items-center rounded-full bg-muted px-2 text-xs">{due}</span> : null}
        {amount ? <span className="inline-flex h-6 items-center rounded-full bg-chart-2/20 px-2 text-xs tabular-nums">{amount}</span> : null}
      </div>
      {subtitle ? <p className="truncate text-xs text-muted-foreground">{subtitle}</p> : null}
      {progress && typeof progress.done === "number" && typeof progress.total === "number" ? (
        <div>
          <div className="h-1.5 overflow-hidden rounded-full bg-muted">
            <div className="h-full rounded-full bg-primary" style={{ width: `${progress.total ? (progress.done / progress.total) * 100 : 0}%` }} />
          </div>
          <p className="mt-1 text-xs text-muted-foreground">{progress.done} of {progress.total}</p>
        </div>
      ) : null}
    </div>
  )
}

function groupKeyOf(record: MultiRecord | undefined, fieldId: string): string | null {
  if (!record) return null
  const value = record[fieldId]
  return value == null ? "" : String(value)
}

function Column({
  id,
  className,
  children,
}: {
  id: string
  className?: string
  children: React.ReactNode
}) {
  const { setNodeRef, isOver } = useDroppable({ id })
  return (
    <section
      ref={setNodeRef}
      className={cn(
        "flex w-64 shrink-0 snap-start flex-col gap-2 rounded-xl bg-muted/50 p-2",
        isOver && "ring-2 ring-ring",
        className,
      )}
    >
      {children}
    </section>
  )
}

function Card({
  record,
  fields,
  titleField,
  cardFields,
  locale,
  groupKey,
  selected,
  onSelectedChange,
  onOpen,
  onDelete,
  reduced,
  className,
  moveLabel,
  groups,
  onMoveTo,
  highlighted = false,
  layout = "fields",
}: {
  record: MultiRecord
  fields: readonly FieldDef[]
  titleField?: string
  cardFields: readonly FieldDef[]
  locale?: string
  groupKey: string
  selected: boolean
  onSelectedChange: (checked: boolean) => void
  onOpen?: (id: string) => void
  onDelete?: (ids: readonly string[]) => Promise<void> | void
  reduced: boolean
  className?: string
  moveLabel: string
  groups: readonly { key: string; label: string }[]
  onMoveTo: (key: string) => void
  highlighted?: boolean
  layout?: "fields" | "summary"
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: record.id,
  })
  const title = recordTitle(record, fields, titleField)
  const [ring, setRing] = React.useState(highlighted)
  const [tracked, setTracked] = React.useState(highlighted)
  if (highlighted !== tracked) {
    setTracked(highlighted)
    setRing(highlighted)
  }
  React.useEffect(() => {
    if (!ring) return
    const timer = window.setTimeout(() => setRing(false), 2000)
    return () => window.clearTimeout(timer)
  }, [ring])
  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition: reduced ? undefined : transition,
  }
  return (
    <article
      ref={setNodeRef}
      style={style}
      data-highlight={ring ? "true" : undefined}
      className={cn(
        "rounded-lg border border-border bg-card p-2",
        isDragging && "opacity-50",
        ring && "ring-2 ring-primary transition-opacity motion-reduce:transition-none",
        className,
      )}
    >
      <div className="flex items-start gap-2">
        <Checkbox
          aria-label={`Select ${title}`}
          checked={selected}
          onCheckedChange={(value) => onSelectedChange(value === true)}
        />
        <button
          type="button"
          className="mt-0.5 text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring"
          aria-label={`Drag ${title}`}
          {...attributes}
          {...listeners}
        >
          <GripVertical className="size-3.5" />
        </button>
        <button
          type="button"
          className="min-w-0 flex-1 truncate rounded-sm text-left text-sm font-medium focus-visible:ring-2 focus-visible:ring-ring"
          dir="auto"
          onClick={() => onOpen?.(record.id)}
          onKeyDown={(event) => {
            if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return
            const current = groups.findIndex((group) => group.key === groupKey)
            const delta = event.key === "ArrowRight" ? 1 : -1
            const next = groups[current + delta]
            if (!next) return
            event.preventDefault()
            onMoveTo(next.key)
          }}
        >
          {title}
        </button>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button type="button" variant="ghost" size="icon" className="size-7" aria-label={`Actions for ${title}`}>
              <MoreHorizontal className="size-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onSelect={() => onOpen?.(record.id)}>Open</DropdownMenuItem>
            <DropdownMenuLabel>{moveLabel}</DropdownMenuLabel>
            {groups.map((group) => (
              <DropdownMenuItem key={group.key || "empty"} onSelect={() => onMoveTo(group.key)}>
                {group.label}
              </DropdownMenuItem>
            ))}
            {onDelete ? (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem onSelect={() => void onDelete([record.id])}>Delete</DropdownMenuItem>
              </>
            ) : null}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
      {layout === "summary" ? <SummaryChips record={record} /> : (
      <dl className="mt-2 grid gap-1">
        {cardFields.map((field) => (
          <div key={field.id} className="flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground">
            <FieldIcon name={field.icon} className="size-3.5 shrink-0" />
            <FieldDisplay field={field} value={record[field.id]} locale={locale} className="text-foreground" />
          </div>
        ))}
      </dl>
      )}
    </article>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { cn } from "@/lib/utils"

export const PRIORITY_LEVELS = ["low", "medium", "high", "critical"] as const

export type PriorityLevel = (typeof PRIORITY_LEVELS)[number]

export type PriorityBadgeClassNames = {
  root?: string
  glyph?: string
  label?: string
}

export type PriorityBadgeProps = {
  level: PriorityLevel
  label?: string
  variant?: "chip" | "glyph" | "pill"
  /** Pill only. Soft keeps a wash. Solid fills high and critical. */
  appearance?: "soft" | "solid"
  className?: string
  classNames?: PriorityBadgeClassNames
}

const DEFAULT_LABEL: Record<PriorityLevel, string> = {
  low: "Low",
  medium: "Medium",
  high: "High",
  critical: "Critical",
}

export function priorityRank(level: PriorityLevel): number {
  return PRIORITY_LEVELS.indexOf(level) + 1
}

export function comparePriority(a: PriorityLevel, b: PriorityLevel): number {
  return priorityRank(a) - priorityRank(b)
}

function SignalGlyph({ filled, className }: { filled: number; className?: string }) {
  const heights = [4, 7, 10, 13]
  return (
    <svg viewBox="0 0 16 14" className={cn("h-3.5 w-4", className)} aria-hidden>
      {heights.map((height, index) => (
        <rect
          key={height}
          x={index * 4}
          y={14 - height}
          width="2.5"
          height={height}
          rx="0.5"
          className={index < filled ? "fill-current" : "fill-current opacity-30"}
        />
      ))}
    </svg>
  )
}

export function PriorityBadge({
  level,
  label,
  variant = "chip",
  appearance,
  className,
  classNames,
}: PriorityBadgeProps) {
  const text = label ?? DEFAULT_LABEL[level]
  const critical = level === "critical"
  if (variant === "pill") {
    const solid = appearance === "solid" || (appearance !== "soft" && (level === "high" || level === "critical"))
    return (
      <span
        data-slot="priority-badge"
        data-level={level}
        data-variant="pill"
        className={cn(
          "inline-flex h-6 max-w-full items-center rounded-full px-2 text-xs font-medium",
          solid && (level === "high" || level === "critical") && "bg-destructive text-background",
          solid && level !== "high" && level !== "critical" && "bg-foreground text-background",
          !solid && (level === "critical" || level === "high") && "bg-destructive/10 text-destructive",
          !solid && level === "medium" && "bg-chart-4/15 text-foreground",
          !solid && level === "low" && "bg-muted text-foreground",
          className,
          classNames?.root,
        )}
      >
        <span className={cn("truncate", classNames?.label)}>{text}</span>
      </span>
    )
  }
  if (variant === "glyph") {
    return (
      <span className={cn("inline-flex text-foreground", critical && "text-destructive", className, classNames?.root)} aria-label={text}>
        <SignalGlyph filled={priorityRank(level)} className={classNames?.glyph} />
      </span>
    )
  }
  return (
    <span
      data-slot="priority-badge"
      data-level={level}
      className={cn(
        "inline-flex h-6 max-w-full items-center gap-1 rounded-full px-2 text-xs font-medium",
        critical ? "bg-destructive/10 text-destructive" : "bg-muted text-foreground",
        className,
        classNames?.root,
      )}
    >
      <SignalGlyph filled={priorityRank(level)} className={classNames?.glyph} />
      <span className={cn("truncate", classNames?.label)}>{text}</span>
    </span>
  )
}

"use client"

import * as React from "react"
import {
  DndContext,
  DragOverlay,
  PointerSensor,
  useDraggable,
  useDroppable,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core"
import { ChevronLeft, ChevronRight } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import {
  addDays,
  chunkWeeks,
  formatDateLabel,
  formatMonthLabel,
  localToday,
  monthGrid,
  parseDateOnly,
  recordTitle,
  weekdayLabels,
  type FieldDef,
  type MultiRecord,
  type ViewConfig,
} from "@/lib/multi-view"
import { useContainerWidth, usePrefersReducedMotion } from "@/components/ui/multi-view-fields"

export type ViewCalendarProps = {
  records: readonly MultiRecord[]
  fields: readonly FieldDef[]
  config: ViewConfig
  locale?: string
  weekStartsOn?: number
  today?: string
  onOpen?: (id: string) => void
  onMove?: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  todayLabel?: string
  moreLabel?: (count: number) => string
  className?: string
  gridClassName?: string
  cardClassName?: string
  agendaClassName?: string
}

export function ViewCalendar({
  records,
  fields,
  config,
  locale,
  weekStartsOn = 1,
  today,
  onOpen,
  onMove,
  todayLabel = "Today",
  moreLabel = (count) => `+${count} more`,
  className,
  gridClassName,
  cardClassName,
  agendaClassName,
}: ViewCalendarProps) {
  const reduced = usePrefersReducedMotion()
  const [rootRef, width] = useContainerWidth<HTMLDivElement>()
  const agenda = width > 0 && width < 560
  const uid = React.useId().replace(/:/g, "")
  const focusSkip = React.useRef(true)
  const dateField = config.dateField ?? "date"
  const resolvedToday = today ?? localToday()
  const initial = parseDateOnly(resolvedToday) ?? { y: 2026, m: 1, d: 1 }
  const [cursor, setCursor] = React.useState({ y: initial.y, m: initial.m - 1 })
  const [focus, setFocus] = React.useState(resolvedToday)
  React.useEffect(() => {
    if (focusSkip.current) {
      focusSkip.current = false
      return
    }
    document.getElementById(`${uid}-${focus}`)?.focus()
  }, [focus, uid])
  const days = React.useMemo(
    () => monthGrid(cursor.y, cursor.m, weekStartsOn),
    [cursor.m, cursor.y, weekStartsOn],
  )
  const weeks = chunkWeeks(days)
  const headers = weekdayLabels(locale, weekStartsOn)
  const byDay = React.useMemo(() => {
    const map = new Map<string, MultiRecord[]>()
    for (const record of records) {
      const iso = record[dateField]
      if (typeof iso !== "string" || !parseDateOnly(iso)) continue
      const list = map.get(iso)
      if (list) list.push(record)
      else map.set(iso, [record])
    }
    return map
  }, [dateField, records])

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 6 } }))

  function shiftMonth(delta: number) {
    setCursor((current) => {
      const index = current.y * 12 + current.m + delta
      return { y: Math.floor(index / 12), m: ((index % 12) + 12) % 12 }
    })
  }

  function goToday() {
    const parts = parseDateOnly(resolvedToday)
    if (!parts) return
    setCursor({ y: parts.y, m: parts.m - 1 })
    setFocus(resolvedToday)
  }

  function moveFocus(iso: string, delta: number) {
    const next = addDays(iso, delta)
    if (!next) return
    const parts = parseDateOnly(next)
    if (parts) setCursor({ y: parts.y, m: parts.m - 1 })
    setFocus(next)
  }

  function reschedule(id: string, iso: string) {
    void onMove?.(id, { [dateField]: iso })
  }

  function onDragEnd(event: DragEndEvent) {
    const over = event.over ? String(event.over.id) : ""
    if (!over.startsWith("day:")) return
    reschedule(String(event.active.id), over.slice(4))
  }

  const monthName = formatMonthLabel(cursor.y, cursor.m, locale)

  return (
    <div ref={rootRef} data-reduced-motion={reduced ? "true" : "false"} className={cn("@container flex min-w-0 flex-col gap-3", className)}>
      <div className="flex flex-wrap items-center gap-2">
        <h2 className="w-full text-sm font-medium @[28rem]:w-auto @[28rem]:flex-1">{monthName}</h2>
        <label className="sr-only" htmlFor={`${uid}-month`}>
          Month
        </label>
        <input
          id={`${uid}-month`}
          type="month"
          className="h-8 rounded-md border border-input bg-background px-2 text-sm"
          value={`${cursor.y}-${String(cursor.m + 1).padStart(2, "0")}`}
          onChange={(event) => {
            const [y, m] = event.target.value.split("-").map(Number)
            if (!y || !m) return
            setCursor({ y, m: m - 1 })
          }}
        />
        <Button type="button" variant="outline" size="icon" className="size-8" aria-label="Previous month" onClick={() => shiftMonth(-1)}>
          <ChevronLeft className="size-4" />
        </Button>
        <Button type="button" variant="outline" size="icon" className="size-8" aria-label="Next month" onClick={() => shiftMonth(1)}>
          <ChevronRight className="size-4" />
        </Button>
        <Button type="button" variant="outline" size="sm" onClick={goToday}>
          {todayLabel}
        </Button>
      </div>
      {agenda ? (
        <Agenda
          days={days.filter((day) => day.inMonth)}
          byDay={byDay}
          fields={fields}
          titleField={config.titleField}
          today={resolvedToday}
          locale={locale}
          dateField={dateField}
          onOpen={onOpen}
          onReschedule={reschedule}
          className={agendaClassName}
          cardClassName={cardClassName}
        />
      ) : (
        <DndContext sensors={sensors} onDragEnd={onDragEnd}>
          <div
            role="grid"
            aria-label={monthName}
            className={cn("grid min-w-0 gap-px overflow-hidden rounded-lg border border-border bg-border", gridClassName)}
          >
            <div role="row" className="grid grid-cols-7 gap-px">
              {headers.map((label) => (
                <div key={label} role="columnheader" className="bg-muted px-1 py-1 text-center text-xs text-muted-foreground">
                  {label}
                </div>
              ))}
            </div>
            {weeks.map((week, weekIndex) => (
              <div role="row" key={week[0]?.iso ?? weekIndex} className="grid grid-cols-7 gap-px">
                {week.map((day) => (
                  <DayCell
                    key={day.iso}
                    cellId={`${uid}-${day.iso}`}
                    iso={day.iso}
                    inMonth={day.inMonth}
                    today={day.iso === resolvedToday}
                    focused={focus === day.iso}
                    records={byDay.get(day.iso) ?? []}
                    fields={fields}
                    titleField={config.titleField}
                    locale={locale}
                    moreLabel={moreLabel}
                    cardClassName={cardClassName}
                    onFocus={() => setFocus(day.iso)}
                    onKeyDown={(event) => {
                      if (event.altKey || event.target !== event.currentTarget) return
                      const delta =
                        event.key === "ArrowRight" ? 1 :
                        event.key === "ArrowLeft" ? -1 :
                        event.key === "ArrowDown" ? 7 :
                        event.key === "ArrowUp" ? -7 : 0
                      if (!delta) return
                      event.preventDefault()
                      moveFocus(day.iso, delta)
                    }}
                    onOpen={onOpen}
                    onReschedule={reschedule}
                    dateField={dateField}
                  />
                ))}
              </div>
            ))}
          </div>
          <DragOverlay dropAnimation={reduced ? null : undefined} />
        </DndContext>
      )}
    </div>
  )
}

function DayCell({
  cellId,
  iso,
  inMonth,
  today,
  focused,
  records,
  fields,
  titleField,
  locale,
  moreLabel,
  cardClassName,
  onFocus,
  onKeyDown,
  onOpen,
  onReschedule,
  dateField,
}: {
  cellId: string
  iso: string
  inMonth: boolean
  today: boolean
  focused: boolean
  records: readonly MultiRecord[]
  fields: readonly FieldDef[]
  titleField?: string
  locale?: string
  moreLabel: (count: number) => string
  cardClassName?: string
  onFocus: () => void
  onKeyDown: (event: React.KeyboardEvent) => void
  onOpen?: (id: string) => void
  onReschedule: (id: string, iso: string) => void
  dateField: string
}) {
  const { setNodeRef, isOver } = useDroppable({ id: `day:${iso}` })
  const visible = records.slice(0, 2)
  const hidden = records.slice(2)
  const parts = parseDateOnly(iso)
  return (
    <div
      ref={setNodeRef}
      id={cellId}
      role="gridcell"
      tabIndex={focused ? 0 : -1}
      aria-selected={focused}
      aria-current={today ? "date" : undefined}
      aria-label={formatDateLabel(iso, locale)}
      data-today={today ? "true" : "false"}
      onFocus={(event) => {
        if (event.target !== event.currentTarget) return
        onFocus()
      }}
      onKeyDown={onKeyDown}
      className={cn(
        "flex min-h-24 min-w-0 flex-col gap-1 bg-background p-1 outline-none focus-visible:ring-2 focus-visible:ring-ring",
        !inMonth && "bg-muted/40 text-muted-foreground",
        isOver && "bg-accent",
      )}
    >
      <span className={cn("inline-flex size-6 items-center justify-center rounded-full text-xs", today && "bg-primary text-primary-foreground")}>
        {parts?.d}
      </span>
      {visible.map((record) => (
        <RecordChip
          key={record.id}
          record={record}
          fields={fields}
          titleField={titleField}
          className={cardClassName}
          onOpen={onOpen}
          onReschedule={(delta) => {
            const next = addDays(iso, delta)
            if (next) onReschedule(record.id, next)
          }}
          dateField={dateField}
        />
      ))}
      {hidden.length ? (
        <Popover>
          <PopoverTrigger asChild>
            <button type="button" className="text-left text-xs text-muted-foreground underline-offset-2 hover:underline">
              {moreLabel(hidden.length)}
            </button>
          </PopoverTrigger>
          <PopoverContent className="grid gap-1">
            {hidden.map((record) => (
              <button key={record.id} type="button" className="truncate text-left text-sm" onClick={() => onOpen?.(record.id)}>
                {recordTitle(record, fields, titleField)}
              </button>
            ))}
          </PopoverContent>
        </Popover>
      ) : null}
    </div>
  )
}

function RecordChip({
  record,
  fields,
  titleField,
  className,
  onOpen,
  onReschedule,
}: {
  record: MultiRecord
  fields: readonly FieldDef[]
  titleField?: string
  className?: string
  onOpen?: (id: string) => void
  onReschedule: (delta: number) => void
  dateField: string
}) {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({ id: record.id })
  const title = recordTitle(record, fields, titleField)
  return (
    <button
      ref={setNodeRef}
      type="button"
      className={cn(
        "truncate rounded-md bg-muted px-1.5 py-0.5 text-left text-xs focus-visible:ring-2 focus-visible:ring-ring",
        isDragging && "opacity-40",
        className,
      )}
      aria-label={`Reschedule ${title}`}
      dir="auto"
      onClick={() => onOpen?.(record.id)}
      {...attributes}
      {...listeners}
      onKeyDown={(event) => {
        if (event.altKey && (event.key === "ArrowLeft" || event.key === "ArrowRight")) {
          event.preventDefault()
          event.stopPropagation()
          onReschedule(event.key === "ArrowRight" ? 1 : -1)
          return
        }
        listeners?.onKeyDown?.(event)
      }}
    >
      {title}
    </button>
  )
}

function Agenda({
  days,
  byDay,
  fields,
  titleField,
  today,
  locale,
  onOpen,
  onReschedule,
  className,
  cardClassName,
}: {
  days: { iso: string; inMonth: boolean }[]
  byDay: Map<string, MultiRecord[]>
  fields: readonly FieldDef[]
  titleField?: string
  today: string
  locale?: string
  dateField: string
  onOpen?: (id: string) => void
  onReschedule: (id: string, iso: string) => void
  className?: string
  cardClassName?: string
}) {
  const listed = days.filter((day) => day.iso === today || (byDay.get(day.iso)?.length ?? 0) > 0)
  return (
    <ol className={cn("grid gap-3", className)}>
      {listed.map((day) => (
        <li key={day.iso} className="grid gap-1">
          <h3 className={cn("text-xs font-medium", day.iso === today && "text-primary")}>
            {formatDateLabel(day.iso, locale)}
          </h3>
          {(byDay.get(day.iso) ?? []).map((record) => (
            <button
              key={record.id}
              type="button"
              className={cn("truncate rounded-md border border-border bg-card px-2 py-1 text-left text-sm", cardClassName)}
              dir="auto"
              onClick={() => onOpen?.(record.id)}
              onKeyDown={(event) => {
                if (!event.altKey || (event.key !== "ArrowLeft" && event.key !== "ArrowRight")) return
                const next = addDays(day.iso, event.key === "ArrowRight" ? 1 : -1)
                if (!next) return
                event.preventDefault()
                onReschedule(record.id, next)
              }}
            >
              {recordTitle(record, fields, titleField)}
            </button>
          ))}
          {(byDay.get(day.iso) ?? []).length === 0 ? (
            <p className="text-sm text-muted-foreground">No items</p>
          ) : null}
        </li>
      ))}
    </ol>
  )
}

"use client"

import * as React from "react"
import { ChevronDown } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  asDateRange,
  barPlacement,
  formatDateLabel,
  groupRecords,
  localToday,
  moveRange,
  parseDateOnly,
  recordTitle,
  resizeRange,
  timelineRange,
  timelineTicks,
  type FieldDef,
  type MultiRecord,
  type TimelineZoom,
  type ViewConfig,
} from "@/lib/multi-view"
import { usePrefersReducedMotion } from "@/components/ui/multi-view-fields"

const UNIT: Record<TimelineZoom, number> = {
  day: 28,
  week: 36,
  month: 72,
  quarter: 88,
}

const ZOOMS: TimelineZoom[] = ["day", "week", "month", "quarter"]

export type ViewTimelineProps = {
  records: readonly MultiRecord[]
  fields: readonly FieldDef[]
  config: ViewConfig
  locale?: string
  weekStartsOn?: number
  today?: string
  zoom?: TimelineZoom
  onZoomChange?: (zoom: TimelineZoom) => void
  onOpen?: (id: string) => void
  onMove?: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  className?: string
  rowClassName?: string
  barClassName?: string
}

export function ViewTimeline({
  records,
  fields,
  config,
  locale,
  weekStartsOn = 1,
  today,
  zoom: zoomProp,
  onZoomChange,
  onOpen,
  onMove,
  className,
  rowClassName,
  barClassName,
}: ViewTimelineProps) {
  const reduced = usePrefersReducedMotion()
  const [zoomState, setZoomState] = React.useState<TimelineZoom>("week")
  const zoom = zoomProp ?? zoomState
  const setZoom = (next: TimelineZoom) => {
    if (zoomProp === undefined) setZoomState(next)
    onZoomChange?.(next)
  }
  const startField = config.startField ?? "start"
  const endField = config.endField ?? "end"
  const resolvedToday = today ?? localToday()
  const groups = groupRecords(records, fields, config.groupField, { includeEmpty: false, locale })
  const range = timelineRange(records, startField, endField, zoom, resolvedToday, weekStartsOn)
  const ticks = timelineTicks(range.start, range.end, zoom, locale, weekStartsOn)
  const width = Math.max(ticks.length, 1) * UNIT[zoom]
  const todayIndex = ticks.findIndex((tick) => tick.iso === snap(resolvedToday, zoom, weekStartsOn))

  function commit(id: string, start: string, end: string) {
    void onMove?.(id, { [startField]: start, [endField]: end })
  }

  return (
    <div data-reduced-motion={reduced ? "true" : "false"} className={cn("flex min-w-0 flex-col gap-3", className)}>
      <div className="flex flex-wrap gap-1" role="group" aria-label="Zoom">
        {ZOOMS.map((item) => (
          <Button
            key={item}
            type="button"
            size="sm"
            variant={item === zoom ? "default" : "outline"}
            aria-pressed={item === zoom}
            onClick={() => setZoom(item)}
          >
            {item}
          </Button>
        ))}
      </div>
      <div className="min-w-0 overflow-x-auto rounded-lg border border-border">
        <div className="relative" style={{ minWidth: width + 180 }}>
          <div className="sticky top-0 z-10 flex border-b border-border bg-muted">
            <div className="sticky left-0 w-44 shrink-0 border-r border-border bg-muted px-2 py-1 text-xs text-muted-foreground">
              Group
            </div>
            <div className="relative" style={{ width }}>
              {ticks.map((tick) => (
                <span
                  key={tick.iso}
                  className="absolute top-0 border-l border-border px-1 py-1 text-[10px] text-muted-foreground"
                  style={{ left: ticks.indexOf(tick) * UNIT[zoom], width: UNIT[zoom] }}
                >
                  {tick.label}
                </span>
              ))}
              <div className="h-7" />
              {todayIndex >= 0 ? (
                <div
                  aria-hidden
                  className="absolute top-0 bottom-0 w-px bg-primary"
                  style={{ left: todayIndex * UNIT[zoom] }}
                />
              ) : null}
            </div>
          </div>
          {groups.map((group) => (
            <GroupBlock
              key={group.key || "all"}
              label={group.label}
              records={group.records}
              fields={fields}
              config={config}
              startField={startField}
              endField={endField}
              rangeStart={range.start}
              zoom={zoom}
              weekStartsOn={weekStartsOn}
              unit={UNIT[zoom]}
              width={width}
              locale={locale}
              reduced={reduced}
              rowClassName={rowClassName}
              barClassName={barClassName}
              onOpen={onOpen}
              onCommit={commit}
            />
          ))}
        </div>
      </div>
    </div>
  )
}

function snap(iso: string, zoom: TimelineZoom, weekStartsOn: number) {
  if (zoom === "day") return iso
  const ticks = timelineTicks(iso, iso, zoom, undefined, weekStartsOn)
  return ticks[0]?.iso ?? iso
}

function GroupBlock({
  label,
  records,
  fields,
  config,
  startField,
  endField,
  rangeStart,
  zoom,
  weekStartsOn,
  unit,
  width,
  locale,
  reduced,
  rowClassName,
  barClassName,
  onOpen,
  onCommit,
}: {
  label: string
  records: readonly MultiRecord[]
  fields: readonly FieldDef[]
  config: ViewConfig
  startField: string
  endField: string
  rangeStart: string
  zoom: TimelineZoom
  weekStartsOn: number
  unit: number
  width: number
  locale?: string
  reduced: boolean
  rowClassName?: string
  barClassName?: string
  onOpen?: (id: string) => void
  onCommit: (id: string, start: string, end: string) => void
}) {
  const [open, setOpen] = React.useState(true)
  return (
    <section>
      <button
        type="button"
        className="flex w-full items-center gap-2 border-b border-border bg-muted/40 px-2 py-1 text-left text-sm font-medium"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
      >
        <ChevronDown className={cn("size-4 transition-transform motion-reduce:transition-none", !open && "-rotate-90")} />
        <span>{label}</span>
        <span className="text-xs text-muted-foreground">{records.length}</span>
      </button>
      {open
        ? records.map((record) => (
            <TimelineRow
              key={record.id}
              record={record}
              fields={fields}
              titleField={config.titleField}
              startField={startField}
              endField={endField}
              rangeStart={rangeStart}
              zoom={zoom}
              weekStartsOn={weekStartsOn}
              unit={unit}
              width={width}
              locale={locale}
              reduced={reduced}
              className={rowClassName}
              barClassName={barClassName}
              onOpen={onOpen}
              onCommit={onCommit}
            />
          ))
        : null}
    </section>
  )
}

function readRange(record: MultiRecord, startField: string, endField: string) {
  const directStart = record[startField]
  const directEnd = record[endField]
  if (typeof directStart === "string" && typeof directEnd === "string" && parseDateOnly(directStart) && parseDateOnly(directEnd)) {
    return { start: directStart, end: directEnd }
  }
  return asDateRange(record[startField])
}

function TimelineRow({
  record,
  fields,
  titleField,
  startField,
  endField,
  rangeStart,
  zoom,
  weekStartsOn,
  unit,
  width,
  locale,
  reduced,
  className,
  barClassName,
  onOpen,
  onCommit,
}: {
  record: MultiRecord
  fields: readonly FieldDef[]
  titleField?: string
  startField: string
  endField: string
  rangeStart: string
  zoom: TimelineZoom
  weekStartsOn: number
  unit: number
  width: number
  locale?: string
  reduced: boolean
  className?: string
  barClassName?: string
  onOpen?: (id: string) => void
  onCommit: (id: string, start: string, end: string) => void
}) {
  const title = recordTitle(record, fields, titleField)
  const range = readRange(record, startField, endField)
  const place = range ? barPlacement(rangeStart, range.start, range.end, zoom, weekStartsOn) : null
  const drag = React.useRef<{ edge: "move" | "start" | "end"; x: number; start: string; end: string } | null>(null)

  function onPointerDown(event: React.PointerEvent<HTMLButtonElement>, edge: "move" | "start" | "end") {
    if (!range) return
    event.currentTarget.setPointerCapture(event.pointerId)
    drag.current = { edge, x: event.clientX, start: range.start, end: range.end }
  }

  function onPointerUp(event: React.PointerEvent<HTMLButtonElement>) {
    const session = drag.current
    drag.current = null
    if (!session) return
    const units = Math.round((event.clientX - session.x) / unit)
    if (!units) {
      if (session.edge === "move") onOpen?.(record.id)
      return
    }
    const next =
      session.edge === "move"
        ? moveRange(session.start, session.end, zoom, units)
        : resizeRange(session.start, session.end, session.edge, zoom, units)
    if (next) onCommit(record.id, next.start, next.end)
  }

  function onKeyDown(event: React.KeyboardEvent) {
    if (!range) return
    const dir = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0
    if (!dir) return
    event.preventDefault()
    const next = event.shiftKey
      ? resizeRange(range.start, range.end, "end", zoom, dir)
      : moveRange(range.start, range.end, zoom, dir)
    if (next) onCommit(record.id, next.start, next.end)
  }

  const name = range
    ? `${title}, ${formatDateLabel(range.start, locale)} to ${formatDateLabel(range.end, locale)}`
    : title

  return (
    <div className={cn("flex border-b border-border", className)}>
      <div className="sticky left-0 z-10 flex w-44 shrink-0 items-center border-r border-border bg-background px-2">
        <span className="truncate text-sm" dir="auto">
          {title}
        </span>
      </div>
      <div className="relative h-10" style={{ width }}>
        {place && range ? (
          <button
            type="button"
            className={cn(
              "absolute top-2 flex h-6 items-center overflow-hidden rounded-md bg-primary/15 px-2 text-xs text-foreground ring-1 ring-primary/30 focus-visible:ring-2 focus-visible:ring-ring",
              reduced && "transition-none",
              barClassName,
            )}
            style={{ left: place.offset * unit, width: Math.max(place.span * unit - 4, 16) }}
            aria-label={name}
            onKeyDown={onKeyDown}
            onPointerDown={(event) => onPointerDown(event, edgeFromTarget(event))}
            onPointerUp={onPointerUp}
          >
            <span className="absolute inset-y-0 left-0 w-1.5 cursor-ew-resize" data-edge="start" />
            <span className="pointer-events-none truncate" dir="auto">
              {title}
            </span>
            <span className="absolute inset-y-0 right-0 w-1.5 cursor-ew-resize" data-edge="end" />
          </button>
        ) : (
          <span className="px-2 text-xs text-muted-foreground">No dates</span>
        )}
      </div>
    </div>
  )
}

function edgeFromTarget(event: React.PointerEvent<HTMLButtonElement>): "move" | "start" | "end" {
  const node = event.target instanceof Element ? event.target.closest("[data-edge]") : null
  const edge = node?.getAttribute("data-edge")
  if (edge === "start" || edge === "end") return edge
  return "move"
}

