export type ViewGroupedListProps = {
  records: readonly MultiRecord[]
  fields: readonly FieldDef[]
  config: ViewConfig
  locale?: string
  onOpen?: (id: string) => void
  emptyLabel?: string
  className?: string
  groupClassName?: string
  rowClassName?: string
}

