export type RecordPropertiesProps = {
  record: MultiRecord
  fields: readonly FieldDef[]
  locale?: string
  onChange?: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  className?: string
  sectionClassName?: string
  rowClassName?: string
  labelClassName?: string
  valueClassName?: string
}

export function RecordProperties({
  record,
  fields,
  locale,
  onChange,
  className,
  sectionClassName,
  rowClassName,
  labelClassName,
  valueClassName,
}: RecordPropertiesProps) {
  const sections = React.useMemo(() => {
    const map = new Map<string, FieldDef[]>()
    for (const field of fields) {
      const name = field.section ?? "Details"
      const list = map.get(name)
      if (list) list.push(field)
      else map.set(name, [field])
    }
    return [...map.entries()]
  }, [fields])

  return (
    <div className={cn("@container flex flex-col gap-5", className)}>
      {sections.map(([name, sectionFields]) => (
        <section key={name} className={sectionClassName}>
          <h3 className="mb-2 text-xs font-medium tracking-wide text-muted-foreground uppercase">{name}</h3>
          <div className="grid gap-1">
            {sectionFields.map((field) => (
              <PropertyRow
                key={field.id}
                record={record}
                field={field}
                locale={locale}
                onChange={onChange}
                className={rowClassName}
                labelClassName={labelClassName}
                valueClassName={valueClassName}
              />
            ))}
          </div>
        </section>
      ))}
    </div>
  )
}

function PropertyRow({
  record,
  field,
  locale,
  onChange,
  className,
  labelClassName,
  valueClassName,
}: {
  record: MultiRecord
  field: FieldDef
  locale?: string
  onChange?: (id: string, patch: Record<string, unknown>) => Promise<void> | void
  className?: string
  labelClassName?: string
  valueClassName?: string
}) {
  const [editing, setEditing] = React.useState(false)
  const [draft, setDraft] = React.useState("")
  const [pending, setPending] = React.useState<unknown>(undefined)
  const [hasPending, setHasPending] = React.useState(false)
  const value = hasPending ? pending : record[field.id]

  async function commit(next: unknown) {
    setPending(next)
    setHasPending(true)
    setEditing(false)
    try {
      await onChange?.(record.id, { [field.id]: next })
      setHasPending(false)
    } catch {
      setHasPending(false)
      setPending(undefined)
    }
  }

  function start() {
    if (field.readOnly || !onChange) return
    if (field.type === "text" || field.type === "url" || field.type === "number" || field.type === "currency" || field.type === "progress") {
      const current = record[field.id]
      setDraft(current == null ? "" : String(current))
      setEditing(true)
      return
    }
    if (field.type === "person" || field.type === "relation") {
      setDraft(asPerson(record[field.id])?.name ?? "")
      setEditing(true)
    }
  }

  function cancel() {
    setEditing(false)
  }

  async function commitDraft() {
    if (field.type === "number" || field.type === "currency" || field.type === "progress") {
      if (draft.trim() === "") {
        await commit(null)
        return
      }
      const n = Number(draft)
      if (!Number.isFinite(n)) return
      await commit(n)
      return
    }
    if (field.type === "person" || field.type === "relation") {
      await commit(draft.trim() ? { name: draft.trim() } : null)
      return
    }
    await commit(draft)
  }

  return (
    <div className={cn("grid min-w-0 grid-cols-1 items-start gap-1 py-1 @min-[22rem]:grid-cols-[minmax(0,9rem)_minmax(0,1fr)] @min-[22rem]:items-center @min-[22rem]:gap-2", className)}>
      <div className={cn("flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground", labelClassName)}>
        <FieldIcon name={field.icon} className="size-3.5 shrink-0" />
        <span className="truncate">{field.label}</span>
      </div>
      <div className={cn("min-w-0 text-sm break-words", valueClassName)}>
        {field.readOnly || !onChange ? (
          <FieldDisplay field={field} value={value} locale={locale} />
        ) : field.type === "boolean" ? (
          <Checkbox
            aria-label={field.label}
            checked={value === true}
            onCheckedChange={(checked) => void commit(checked === true)}
          />
        ) : field.type === "select" || field.type === "status" ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button type="button" className="rounded-sm text-left focus-visible:ring-2 focus-visible:ring-ring">
                <FieldDisplay field={field} value={value} locale={locale} />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
              {(field.options ?? []).map((option) => (
                <DropdownMenuItem key={option.value} onSelect={() => void commit(option.value)}>
                  {option.label}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        ) : field.type === "date" ? (
          <DateEditor field={field} value={value} locale={locale} onCommit={(next) => void commit(next)} />
        ) : editing ? (
          <Input
            autoFocus
            aria-label={field.label}
            value={draft}
            inputMode={field.type === "number" || field.type === "currency" || field.type === "progress" ? "decimal" : undefined}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault()
                void commitDraft()
              }
              if (event.key === "Escape") {
                event.preventDefault()
                cancel()
              }
            }}
          />
        ) : (
          <button
            type="button"
            className="max-w-full truncate rounded-sm text-left focus-visible:ring-2 focus-visible:ring-ring"
            onClick={start}
          >
            {isEmptyValue(value) ? <span className="text-muted-foreground">Empty</span> : <FieldDisplay field={field} value={value} locale={locale} />}
          </button>
        )}
      </div>
    </div>
  )
}

function DateEditor({
  field,
  value,
  locale,
  onCommit,
}: {
  field: FieldDef
  value: unknown
  locale?: string
  onCommit: (value: string | null) => void
}) {
  const iso = typeof value === "string" && parseDateOnly(value) ? value : ""
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button type="button" className="rounded-sm text-left focus-visible:ring-2 focus-visible:ring-ring" aria-label={field.label}>
          <FieldDisplay field={field} value={value} locale={locale} />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto">
        <Input
          type="date"
          aria-label={field.label}
          defaultValue={iso}
          onChange={(event) => onCommit(event.target.value || null)}
          onKeyDown={(event) => {
            if (event.key === "Escape") event.currentTarget.blur()
          }}
        />
      </PopoverContent>
    </Popover>
  )
}

export function propertySections(fields: readonly FieldDef[]): string[] {
  return [...new Set(fields.map((field) => field.section ?? "Details"))]
}

"use client"

import * as React from "react"
import {
  Building2,
  Calendar,
  Check,
  DollarSign,
  Flag,
  CircleDot,
  Hash,
  ImageIcon,
  Link,
  ListChecks,
  Tag,
  Type,
  UserRound,
} from "lucide-react"

import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import {
  asPerson,
  formatFieldValue,
  isEmptyValue,
  optionTone,
  type ChartTone,
  type FieldDef,
  type FieldIconName,
  type MultiRecord,
} from "@/lib/multi-view"

const ICONS: Record<FieldIconName, React.ComponentType<{ className?: string }>> = {
  text: Type,
  hash: Hash,
  currency: DollarSign,
  calendar: Calendar,
  user: UserRound,
  link: Link,
  image: ImageIcon,
  check: Check,
  status: ListChecks,
  flag: Flag,
  building: Building2,
  progress: CircleDot,
  tag: Tag,
}

const TONE_CLASS: Record<ChartTone, string> = {
  1: "bg-chart-1",
  2: "bg-chart-2",
  3: "bg-chart-3",
  4: "bg-chart-4",
  5: "bg-chart-5",
}

export function toneClass(tone: ChartTone): string {
  return TONE_CLASS[tone]
}

export function FieldIcon({
  name,
  className,
}: {
  name?: FieldIconName
  className?: string
}) {
  if (!name) return null
  const Icon = ICONS[name]
  return <Icon className={className} aria-hidden />
}

export function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (!parts.length) return "?"
  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase()
  return `${parts[0]![0] ?? ""}${parts[1]![0] ?? ""}`.toUpperCase()
}

export function PersonFace({
  name,
  className,
}: {
  name: string
  className?: string
}) {
  return (
    <Avatar size="sm" className={className}>
      <AvatarFallback className="text-[10px]">{initials(name)}</AvatarFallback>
    </Avatar>
  )
}

export function StatusPill({
  field,
  value,
  className,
}: {
  field: FieldDef
  value: unknown
  className?: string
}) {
  if (isEmptyValue(value)) return <span className="text-muted-foreground">—</span>
  const text = formatFieldValue(value, field)
  const index = field.options?.findIndex((option) => option.value === String(value)) ?? 0
  const tone = optionTone(field, String(value), Math.max(0, index))
  return (
    <Badge variant="outline" className={cn("max-w-full", className)}>
      <span className={cn("size-1.5 rounded-full", toneClass(tone))} aria-hidden />
      <span className="truncate">{text}</span>
    </Badge>
  )
}

export function FieldDisplay({
  field,
  value,
  locale,
  className,
}: {
  field: FieldDef
  value: unknown
  locale?: string
  className?: string
}) {
  if (isEmptyValue(value)) {
    return <span className={cn("text-muted-foreground", className)}>—</span>
  }
  if (field.type === "status" || field.type === "select") {
    return <StatusPill field={field} value={value} className={className} />
  }
  if (field.type === "person" || field.type === "relation") {
    const person = asPerson(value)
    if (!person) return <span className="text-muted-foreground">—</span>
    return (
      <span className={cn("inline-flex min-w-0 items-center gap-1.5", className)}>
        <PersonFace name={person.name} />
        <span className="truncate">{person.name}</span>
      </span>
    )
  }
  if (field.type === "progress") {
    const n = typeof value === "number" ? value : Number(value)
    return (
      <span className={cn("inline-flex items-center gap-1.5", className)}>
        <ProgressRing value={Number.isFinite(n) ? n : 0} />
        <span>{formatFieldValue(value, field, locale)}</span>
      </span>
    )
  }
  const text = formatFieldValue(value, field, locale)
  if (field.type === "url" && typeof value === "string") {
    return (
      <a
        href={value}
        className={cn("truncate underline-offset-2 hover:underline", className)}
        dir="auto"
      >
        {text}
      </a>
    )
  }
  return (
    <span className={cn("truncate", className)} dir="auto">
      {text}
    </span>
  )
}

export function ProgressRing({ value, className }: { value: number; className?: string }) {
  const pct = Math.max(0, Math.min(100, value))
  return (
    <svg viewBox="0 0 16 16" className={cn("size-4 shrink-0", className)} aria-hidden>
      <circle cx="8" cy="8" r="6" fill="none" className="stroke-muted" strokeWidth="2" />
      <circle
        cx="8"
        cy="8"
        r="6"
        fill="none"
        className="stroke-primary"
        strokeWidth="2"
        strokeLinecap="round"
        strokeDasharray={`${pct} ${100 - pct}`}
        pathLength={100}
        transform="rotate(-90 8 8)"
      />
    </svg>
  )
}

export function usePrefersReducedMotion() {
  const [reduced, setReduced] = React.useState(false)
  React.useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)")
    const apply = () => setReduced(query.matches)
    apply()
    query.addEventListener("change", apply)
    return () => query.removeEventListener("change", apply)
  }, [])
  return reduced
}

export function useContainerWidth<T extends HTMLElement>() {
  const ref = React.useRef<T>(null)
  const [width, setWidth] = React.useState(0)
  React.useEffect(() => {
    const node = ref.current
    if (!node) return
    const measure = () => setWidth(node.clientWidth)
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(node)
    return () => observer.disconnect()
  }, [])
  return [ref, width] as const
}

export function displayFields(
  fields: readonly FieldDef[],
  ids: readonly string[] | undefined,
  skip: ReadonlySet<string>,
): FieldDef[] {
  const source = ids?.length
    ? ids.map((id) => fields.find((field) => field.id === id)).filter((field): field is FieldDef => Boolean(field))
    : fields
  return source.filter((field) => !skip.has(field.id))
}

export function recordValue(record: MultiRecord, field: FieldDef) {
  return record[field.id]
}

"use client"

import * as React from "react"
import { Dialog } from "radix-ui"
import { X } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Separator } from "@/components/ui/separator"

/**
 * Progressive disclosure surface.
 *
 * Opens as a right-hand peek panel and can expand left into a two-column
 * view without changing route. Built on Radix Dialog (focus trap, scroll
 * lock, Esc / click-outside). Does not import Next.js — pair with
 * `useLayeredPanelUrlState` when you want shareable URLs.
 *
 * `Header` and `ExpandToggle` sit at the top of the primary column and move
 * into the left column when the panel expands. Render them from a child
 * component that returns a fragment, or give a wrapping element `className="contents"`.
 */

export type LayeredPanelMode = "peek" | "full"

const CSS_LENGTH = /^(?:\d*\.?\d+)(?:px|rem|em|vw|vh|%)$/

type LayeredPanelContextValue = {
  open: boolean
  mode: LayeredPanelMode
  setOpen: (open: boolean) => void
  setMode: (mode: LayeredPanelMode) => void
  registerFull: (present: boolean) => void
}

const LayeredPanelContext =
  React.createContext<LayeredPanelContextValue | null>(null)

function useLayeredPanel() {
  const context = React.useContext(LayeredPanelContext)
  if (!context) {
    throw new Error("useLayeredPanel must be used within LayeredPanel.")
  }
  return context
}

function useControllable<T>({
  value,
  defaultValue,
  onChange,
}: {
  value: T | undefined
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue)
  const controlled = value !== undefined
  const current = controlled ? value : uncontrolled

  const setValue = React.useCallback(
    (next: T) => {
      if (!controlled) setUncontrolled(next)
      onChange?.(next)
    },
    [controlled, onChange],
  )

  return [current, setValue] as const
}

function cssLength(value: string | undefined, fallback: string) {
  if (!value) return fallback
  const trimmed = value.trim()
  return CSS_LENGTH.test(trimmed) ? trimmed : fallback
}

type LayeredPanelProps = {
  children?: React.ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  mode?: LayeredPanelMode
  defaultMode?: LayeredPanelMode
  onModeChange?: (mode: LayeredPanelMode) => void
  /** Accessible name announced for the dialog. */
  title?: string
  /** Accessible description. Kept visually hidden. */
  description?: string
  /** Close button label. Default: "Close". */
  closeLabel?: string
  /** Mobile tab for the peek column. Default: "Overview". */
  mobilePeekLabel?: string
  /** Mobile tab for the full column. Default: "Profile". */
  mobileFullLabel?: string
  /** Peek width on desktop. Any single CSS length. Default: 26.25rem (420px). */
  peekWidth?: string
  /** Expanded width on desktop. Any single CSS length. Default: 70vw. */
  fullWidth?: string
  /** Hide the built-in close button when you render your own. */
  showClose?: boolean
  /** Panel surface. Merged onto the dialog content. */
  className?: string
  /** Backdrop. Default uses `bg-foreground` / `bg-background`, not a custom color. */
  overlayClassName?: string
  /** Built-in close button. */
  closeClassName?: string
  /** Mobile tab track, below 1024px. */
  tabsClassName?: string
  /** Each mobile tab button. */
  tabClassName?: string
  /** Grid that holds Header, ExpandToggle, Peek, and Full. */
  gridClassName?: string
}

function LayeredPanelRoot({
  children,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  mode: modeProp,
  defaultMode = "peek",
  onModeChange,
  title = "Details",
  description = "Detail panel",
  closeLabel = "Close",
  mobilePeekLabel = "Overview",
  mobileFullLabel = "Profile",
  peekWidth,
  fullWidth,
  showClose = true,
  className,
  overlayClassName,
  closeClassName,
  tabsClassName,
  tabClassName,
  gridClassName,
}: LayeredPanelProps) {
  const [open, setOpenState] = useControllable({
    value: openProp,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  const [mode, setModeState] = useControllable({
    value: modeProp,
    defaultValue: defaultMode,
    onChange: onModeChange,
  })

  const setOpen = React.useCallback(
    (next: boolean) => {
      setOpenState(next)
      if (!next && modeProp === undefined) setModeState(defaultMode)
    },
    [defaultMode, modeProp, setModeState, setOpenState],
  )

  const setMode = React.useCallback(
    (next: LayeredPanelMode) => {
      setModeState(next)
    },
    [setModeState],
  )
  const [hasFull, setHasFull] = React.useState(false)
  const registerFull = React.useCallback((present: boolean) => {
    setHasFull(present)
  }, [])

  const panelId = React.useId().replace(/:/g, "")
  const peek = cssLength(peekWidth, "26.25rem")
  const full = cssLength(fullWidth, "70vw")
  const contentRef = React.useRef<HTMLDivElement>(null)
  const previousMode = React.useRef(mode)

  React.useEffect(() => {
    if (
      previousMode.current === "full" &&
      mode === "peek" &&
      contentRef.current
    ) {
      const active = document.activeElement
      if (!active || !contentRef.current.contains(active)) {
        contentRef.current.focus()
      }
    }
    previousMode.current = mode
  }, [mode])

  const context = React.useMemo<LayeredPanelContextValue>(
    () => ({ open, mode, setOpen, setMode, registerFull }),
    [mode, open, registerFull, setMode, setOpen],
  )

  return (
    <LayeredPanelContext.Provider value={context}>
      <Dialog.Root open={open} onOpenChange={setOpen} modal>
        <Dialog.Portal>
          <Dialog.Overlay
            data-slot="layered-panel-overlay"
            className={cn(
              "fixed inset-0 z-50 bg-foreground/40 dark:bg-background/80 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0 motion-reduce:animate-none",
              overlayClassName,
            )}
          />
          <Dialog.Content
            ref={contentRef}
            data-slot="layered-panel"
            data-panel-id={panelId}
            data-mode={mode}
            tabIndex={-1}
            onEscapeKeyDown={(event) => {
              if (mode === "full") {
                event.preventDefault()
                setMode("peek")
              }
            }}
            className={cn(
              "fixed inset-y-0 right-0 z-50 flex h-dvh max-h-dvh max-w-full flex-col overflow-hidden border-l border-border bg-background text-foreground shadow-lg outline-none lg:rounded-l-xl",
              "pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)]",
              "data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:slide-out-to-right data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:slide-in-from-right data-[state=open]:duration-300 data-[state=closed]:duration-300 motion-reduce:animate-none",
              className,
            )}
          >
            <style>{`
              [data-panel-id="${panelId}"] { width: min(100%, ${peek}); transition: width 280ms cubic-bezier(0.32, 0.72, 0, 1); }
              [data-panel-id="${panelId}"][data-mode="full"] { width: min(100%, ${full}); }
              [data-panel-id="${panelId}"] .lp-grid { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); }
              @media (min-width: 1024px) {
                [data-panel-id="${panelId}"][data-mode="full"] .lp-grid { grid-template-columns: minmax(0, 1fr) min(100%, ${peek}); }
              }
              @media (max-width: 1023px) {
                [data-panel-id="${panelId}"],
                [data-panel-id="${panelId}"][data-mode="full"] { width: 100%; transition: none; }
              }
              @media (prefers-reduced-motion: reduce) {
                [data-panel-id="${panelId}"] { transition: none; }
              }
            `}</style>
            <Dialog.Title className="sr-only">{title}</Dialog.Title>
            <Dialog.Description className="sr-only">
              {description}
            </Dialog.Description>
            {showClose ? (
              <Dialog.Close asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  aria-label={closeLabel}
                  className={cn(
                    "absolute top-[max(0.75rem,env(safe-area-inset-top))] right-3 z-10 active:scale-[0.96] motion-reduce:active:scale-100",
                    closeClassName,
                  )}
                >
                  <X />
                </Button>
              </Dialog.Close>
            ) : null}
            {hasFull ? (
              <div className={cn("shrink-0 px-3 pt-3 pr-14 lg:hidden", tabsClassName)}>
                <div
                  className="flex rounded-lg bg-muted p-0.5"
                  role="group"
                  aria-label="Panel sections"
                >
                  <ModeButton
                    pressed={mode === "peek"}
                    onClick={() => setMode("peek")}
                    className={tabClassName}
                  >
                    {mobilePeekLabel}
                  </ModeButton>
                  <ModeButton
                    pressed={mode === "full"}
                    onClick={() => setMode("full")}
                    className={tabClassName}
                  >
                    {mobileFullLabel}
                  </ModeButton>
                </div>
              </div>
            ) : null}
            <div className={cn("lp-grid grid min-h-0 flex-1", gridClassName)}>
              {children}
            </div>
          </Dialog.Content>
        </Dialog.Portal>
      </Dialog.Root>
    </LayeredPanelContext.Provider>
  )
}

function ModeButton({
  pressed,
  onClick,
  className,
  children,
}: {
  pressed: boolean
  onClick: () => void
  className?: string
  children: React.ReactNode
}) {
  return (
    <button
      type="button"
      aria-pressed={pressed}
      onClick={onClick}
      className={cn(
        "h-8 flex-1 rounded-lg text-sm font-medium transition-transform active:scale-[0.96] motion-reduce:active:scale-100",
        pressed
          ? "bg-background text-foreground shadow-sm"
          : "text-muted-foreground",
        className,
      )}
    >
      {children}
    </button>
  )
}

type ColumnProps = {
  children?: React.ReactNode
  className?: string
  contentClassName?: string
}

function Peek({ children, className, contentClassName }: ColumnProps) {
  const { mode } = useLayeredPanel()
  return (
    <div
      data-slot="layered-panel-peek"
      className={cn(
        "col-start-1 row-start-3 min-h-0",
        mode === "full" &&
          "max-lg:hidden lg:col-start-2 lg:row-span-3 lg:row-start-1 lg:border-l lg:border-border",
        className,
      )}
    >
      <ScrollArea className="h-full">
        <div
          className={cn(
            "flex min-h-full flex-col",
            mode === "full" && "lg:pt-12",
            contentClassName,
          )}
        >
          {children}
        </div>
      </ScrollArea>
    </div>
  )
}
Peek.displayName = "LayeredPanel.Peek"
;(Peek as typeof Peek & { slot: string }).slot = "peek"

function Full({ children, className, contentClassName }: ColumnProps) {
  const { mode, registerFull } = useLayeredPanel()
  React.useLayoutEffect(() => {
    registerFull(true)
    return () => registerFull(false)
  }, [registerFull])

  return (
    <div
      data-slot="layered-panel-full"
      inert={mode === "full" ? undefined : true}
      className={cn(
        "col-start-1 row-start-3 min-h-0",
        mode === "full" ? "block" : "hidden",
        className,
      )}
    >
      <ScrollArea className="h-full">
        <div className={cn("flex min-h-full flex-col", contentClassName)}>
          {children}
        </div>
      </ScrollArea>
    </div>
  )
}
Full.displayName = "LayeredPanel.Full"
;(Full as typeof Full & { slot: string }).slot = "full"

function Header({
  children,
  className,
}: {
  children?: React.ReactNode
  className?: string
}) {
  return (
    <div
      data-slot="layered-panel-header"
      className={cn(
        "col-start-1 row-start-1 flex flex-col gap-3 px-5 pt-5 pr-14 pb-1",
        className,
      )}
    >
      {children}
    </div>
  )
}
Header.displayName = "LayeredPanel.Header"
;(Header as typeof Header & { slot: string }).slot = "header"

type ExpandToggleProps = {
  /** Label while the panel is peeked. Default: "View full profile". */
  expandLabel?: string
  /** Label while the panel is expanded. Default: "Close profile". */
  collapseLabel?: string
  /** Wrapper that places the control on the grid. */
  className?: string
  /** Passed to the host `Button`. Does not replace its variant. */
  buttonClassName?: string
}

function ExpandToggle({
  expandLabel = "View full profile",
  collapseLabel = "Close profile",
  className,
  buttonClassName,
}: ExpandToggleProps) {
  const { mode, setMode } = useLayeredPanel()
  const expanded = mode === "full"

  return (
    <div className={cn("col-start-1 row-start-2 px-5 py-3", className)}>
      <Button
        type="button"
        variant="secondary"
        aria-expanded={expanded}
        onClick={() => setMode(expanded ? "peek" : "full")}
        className={cn(
