"use client"

import * as React from "react"

import {
  coerceEnabledViews,
  decodeFilters,
  decodeSort,
  encodeFilters,
  encodeSort,
  readEnabledViews,
  viewPersistenceKey,
  type FilterClause,
  type MultiRecord,
  type SortClause,
  type ViewConfig,
  type ViewPersistenceScope,
} from "@/lib/multi-view"

export type UrlAdapter = {
  get: (key: string) => string | null
  set: (key: string, value: string | null) => void
}

/** Plain History API adapter. Stable if you memoize the returned object. */
export function createHistoryAdapter(): UrlAdapter {
  let search = typeof window === "undefined" ? "" : window.location.search
  return {
    get(key) {
      if (typeof window !== "undefined") search = search || window.location.search
      return new URLSearchParams(search).get(key)
    },
    set(key, value) {
      if (typeof window === "undefined") return
      const params = new URLSearchParams(search || window.location.search)
      if (value == null || value === "") params.delete(key)
      else params.set(key, value)
      const qs = params.toString()
      search = qs ? `?${qs}` : ""
      const url = qs ? `${window.location.pathname}?${qs}` : window.location.pathname
      window.history.replaceState(window.history.state, "", url)
    },
  }
}

export type ViewPersistence = {
  scope: ViewPersistenceScope
  /** Collection id. Combined with `scope` into the storage key. */
  id: string
  /** Defaults to localStorage in the browser. Pass a memory store in tests. */
  storage?: Pick<Storage, "getItem" | "setItem">
}

export type UseMultiViewOptions = {
  views: readonly ViewConfig[]
  /** Prefix for query keys. Default `mv`, producing `mv.view`, `mv.q`, and so on. */
  urlPrefix?: string
  url?: UrlAdapter | null
  /** Which views can be selected. Omit it to enable every view, which is the previous behavior. */
  enabledViews?: readonly string[]
  defaultEnabledViews?: readonly string[]
  onEnabledViewsChange?: (ids: string[]) => void
  /** Remembers the enabled set for one project or for every project. At least one view stays on. */
  persistViews?: ViewPersistence
  viewId?: string
  defaultViewId?: string
  onViewIdChange?: (viewId: string) => void
  query?: string
  defaultQuery?: string
  onQueryChange?: (query: string) => void
  filters?: readonly FilterClause[]
  defaultFilters?: readonly FilterClause[]
  onFiltersChange?: (filters: FilterClause[]) => void
  sort?: SortClause | null
  defaultSort?: SortClause | null
  onSortChange?: (sort: SortClause | null) => void
  /** `undefined` follows the active view. `null` is an explicit "no group". */
  groupBy?: string | null
  defaultGroupBy?: string | null
  onGroupByChange?: (groupBy: string | null) => void
  selectedIds?: readonly string[]
  defaultSelectedIds?: readonly string[]
  onSelectedIdsChange?: (ids: string[]) => void
  openId?: string | null
  defaultOpenId?: string | null
  onOpenIdChange?: (id: string | null) => void
}

type UrlSnapshot = {
  viewId?: string
  query?: string
  filters?: FilterClause[]
  sort?: SortClause | null
  groupBy?: string | null
  selectedIds?: string[]
  openId?: string | null
}

function readUrl(adapter: UrlAdapter | null | undefined, prefix: string): UrlSnapshot {
  if (!adapter) return {}
  const key = (name: string) => adapter.get(`${prefix}.${name}`)
  const viewId = key("view")
  const query = key("q")
  const filtersRaw = key("filters")
  const sortRaw = key("sort")
  const group = key("group")
  const open = key("open")
  const selected = key("sel")
  return {
    viewId: viewId || undefined,
    query: query ?? undefined,
    filters: filtersRaw ? decodeFilters(filtersRaw) : undefined,
    sort: sortRaw ? decodeSort(sortRaw) : undefined,
    groupBy: group == null ? undefined : group === "" ? null : group,
    selectedIds: selected ? selected.split(",").filter(Boolean) : undefined,
    openId: open === "" ? null : open,
  }
}

function useControllable<T>(
  controlled: T | undefined,
  uncontrolled: T,
  onChange?: (value: T) => void,
) {
  const [inner, setInner] = React.useState(uncontrolled)
  const isControlled = controlled !== undefined
  const value = isControlled ? controlled : inner
  const setValue = React.useCallback(
    (next: T) => {
      if (!isControlled) setInner(next)
      onChange?.(next)
    },
    [isControlled, onChange],
  )
  return [value, setValue] as const
}

export function useMultiView({
  views,
  urlPrefix = "mv",
  url,
  enabledViews: enabledProp,
  defaultEnabledViews,
  onEnabledViewsChange,
  persistViews,
  viewId: viewIdProp,
  defaultViewId,
  onViewIdChange,
  query: queryProp,
  defaultQuery,
  onQueryChange,
  filters: filtersProp,
  defaultFilters,
  onFiltersChange,
  sort: sortProp,
  defaultSort,
  onSortChange,
  groupBy: groupByProp,
  defaultGroupBy,
  onGroupByChange,
  selectedIds: selectedProp,
  defaultSelectedIds,
  onSelectedIdsChange,
  openId: openProp,
  defaultOpenId,
  onOpenIdChange,
}: UseMultiViewOptions) {
  const initialUrl = React.useState(() => readUrl(url, urlPrefix))[0]
  const viewIds = React.useMemo(() => views.map((view) => view.id), [views])
  const fallbackEnabled = React.useMemo(
    () => coerceEnabledViews(defaultEnabledViews ?? viewIds, viewIds),
    [defaultEnabledViews, viewIds],
  )
  const fallbackView = defaultViewId ?? initialUrl.viewId ?? views[0]?.id ?? ""

  const [enabledViews, setEnabledViews] = useControllable(
    enabledProp as string[] | undefined,
    fallbackEnabled,
    onEnabledViewsChange,
  )
  const [viewId, setViewId] = useControllable(
    viewIdProp,
    fallbackView,
    onViewIdChange,
  )
  const [query, setQuery] = useControllable(
    queryProp,
    defaultQuery ?? initialUrl.query ?? "",
    onQueryChange,
  )
  const [filters, setFilters] = useControllable(
    filtersProp as FilterClause[] | undefined,
    [...(defaultFilters ?? initialUrl.filters ?? [])],
    onFiltersChange,
  )
  const [sort, setSort] = useControllable(
    sortProp,
    defaultSort !== undefined ? defaultSort : (initialUrl.sort ?? null),
    onSortChange,
  )
  const [groupMode, setGroupMode] = React.useState<"view" | "value">(
    defaultGroupBy !== undefined || initialUrl.groupBy !== undefined ? "value" : "view",
  )
  const [groupBy, setGroupByState] = useControllable(
    groupByProp,
    defaultGroupBy !== undefined ? defaultGroupBy : (initialUrl.groupBy ?? null),
    onGroupByChange,
  )
  const setGroupBy = React.useCallback(
    (next: string | null) => {
      setGroupMode("value")
      setGroupByState(next)
    },
    [setGroupByState],
  )
  const [selectedIds, setSelectedIds] = useControllable(
    selectedProp as string[] | undefined,
    [...(defaultSelectedIds ?? initialUrl.selectedIds ?? [])],
    onSelectedIdsChange,
  )
  const [openId, setOpenId] = useControllable(
    openProp,
    defaultOpenId !== undefined ? defaultOpenId : (initialUrl.openId ?? null),
    onOpenIdChange,
  )

  const updateEnabledViews = React.useCallback(
    (next: readonly string[]) => {
      const coerced = coerceEnabledViews(next, viewIds, enabledViews)
      const same =
        coerced.length === enabledViews.length &&
        coerced.every((id, index) => id === enabledViews[index])
      if (same) return
      setEnabledViews(coerced)
      if (!persistViews || typeof window === "undefined") return
      try {
        const store = persistViews.storage ?? window.localStorage
        store.setItem(viewPersistenceKey(persistViews.scope, persistViews.id), JSON.stringify(coerced))
      } catch {
        // A blocked store still leaves the in-memory set in place.
      }
    },
    [enabledViews, persistViews, setEnabledViews, viewIds],
  )

  const loadedViews = React.useRef(false)
  React.useEffect(() => {
    if (loadedViews.current) return
    loadedViews.current = true
    if (!persistViews || enabledProp !== undefined || typeof window === "undefined") return
    try {
      const store = persistViews.storage ?? window.localStorage
      const stored = readEnabledViews(
        store.getItem(viewPersistenceKey(persistViews.scope, persistViews.id)),
        viewIds,
      )
      if (stored) updateEnabledViews(stored)
    } catch {
      // Ignore an unreadable store and keep the default set.
    }
  }, [enabledProp, persistViews, updateEnabledViews, viewIds])

  const requestedView = React.useRef<string | null>(null)
  React.useEffect(() => {
    if (enabledViews.includes(viewId)) {
      requestedView.current = null
      return
    }
    const next = enabledViews[0]
    if (!next || requestedView.current === next) return
    requestedView.current = next
    setViewId(next)
  }, [enabledViews, setViewId, viewId])

  const active = views.find((view) => view.id === viewId) ?? views.find((view) => enabledViews.includes(view.id)) ?? views[0]
  const resolvedGroupBy =
    groupByProp !== undefined || groupMode === "value" ? groupBy : (active?.groupField ?? null)

  React.useEffect(() => {
    if (!url) return
    url.set(`${urlPrefix}.view`, viewId || null)
    url.set(`${urlPrefix}.q`, query || null)
    url.set(`${urlPrefix}.filters`, filters.length ? encodeFilters(filters) : null)
    url.set(`${urlPrefix}.sort`, encodeSort(sort))
    url.set(`${urlPrefix}.group`, resolvedGroupBy)
    url.set(`${urlPrefix}.sel`, selectedIds.length ? selectedIds.join(",") : null)
    url.set(`${urlPrefix}.open`, openId)
  }, [filters, openId, query, resolvedGroupBy, selectedIds, sort, url, urlPrefix, viewId])

  React.useEffect(() => {
    if (!url || viewIdProp !== undefined) return
    const onPop = () => {
      const next = readUrl(url, urlPrefix)
      if (next.viewId) setViewId(next.viewId)
      if (next.query !== undefined) setQuery(next.query)
    }
    window.addEventListener("popstate", onPop)
    return () => window.removeEventListener("popstate", onPop)
  }, [setQuery, setViewId, url, urlPrefix, viewIdProp])

  const toggleSelected = React.useCallback(
    (id: string, selected?: boolean) => {
      const has = selectedIds.includes(id)
      const nextSelected = selected ?? !has
      const next = nextSelected
        ? has
          ? selectedIds
          : [...selectedIds, id]
        : selectedIds.filter((item) => item !== id)
      setSelectedIds([...next])
    },
    [selectedIds, setSelectedIds],
  )

  const clearSelection = React.useCallback(() => {
    setSelectedIds([])
  }, [setSelectedIds])

  return {
    views,
    enabledViews,
    setEnabledViews: updateEnabledViews,
    active,
    viewId,
    setViewId,
    query,
    setQuery,
    filters,
    setFilters,
    sort,
    setSort,
    groupBy: resolvedGroupBy,
    setGroupBy,
    selectedIds,
    setSelectedIds,
    toggleSelected,
    clearSelection,
    openId,
    setOpenId,
  }
}

export type OptimisticHandlers<T extends MultiRecord> = {
  records: readonly T[]
  onRecordChange?: (id: string, patch: Partial<T>) => Promise<void> | void
  onCreate?: (draft: Partial<T>) => Promise<void> | void
  onDelete?: (ids: readonly string[]) => Promise<void> | void
  onMove?: (id: string, patch: Partial<T>) => Promise<void> | void
}

/**
 * Applies a patch immediately and restores the previous row if the callback rejects.
 * Incoming `records` replace a patch once every patched key matches.
 */
export function useOptimisticRecords<T extends MultiRecord>({
  records,
  onRecordChange,
  onCreate,
  onDelete,
  onMove,
}: OptimisticHandlers<T>) {
  const [patches, setPatches] = React.useState<Record<string, Partial<T>>>({})
  const [added, setAdded] = React.useState<T[]>([])
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(new Set())
  const [seen, setSeen] = React.useState(records)
  if (seen !== records) {
    setSeen(records)
    setPatches((prev) => {
      let changed = false
      const next = { ...prev }
      for (const [id, patch] of Object.entries(prev)) {
        const record = records.find((item) => item.id === id)
        if (!record) continue
        const applied = Object.entries(patch).every(([key, value]) =>
          Object.is(record[key as keyof T], value),
        )
        if (applied) {
          delete next[id]
          changed = true
        }
      }
      return changed ? next : prev
    })
    setAdded((prev) => prev.filter((item) => !records.some((record) => record.id === item.id)))
    setHidden((prev) => {
      if (prev.size === 0) return prev
      const next = new Set([...prev].filter((id) => records.some((record) => record.id === id)))
      return next.size === prev.size ? prev : next
    })
  }

  const view = React.useMemo(() => {
    const base = records
      .filter((record) => !hidden.has(record.id))
      .map((record) => (patches[record.id] ? ({ ...record, ...patches[record.id] } as T) : record))
    const extras = added.filter(
      (record) => !records.some((item) => item.id === record.id) && !hidden.has(record.id),
    )
    return [...base, ...extras]
  }, [added, hidden, patches, records])

  const change = React.useCallback(
    async (id: string, patch: Partial<T>, commit?: (id: string, patch: Partial<T>) => Promise<void> | void) => {
      let snapshot: Partial<T> | undefined
      let had = false
      setPatches((prev) => {
        had = Object.prototype.hasOwnProperty.call(prev, id)
        snapshot = prev[id]
        return { ...prev, [id]: { ...prev[id], ...patch } }
      })
      try {
        await commit?.(id, patch)
      } catch (error) {
        setPatches((prev) => {
          const rolled = { ...prev }
          if (had && snapshot) rolled[id] = snapshot
          else delete rolled[id]
          return rolled
        })
        throw error
      }
    },
    [],
  )

  const update = React.useCallback(
    (id: string, patch: Partial<T>) => change(id, patch, onRecordChange),
    [change, onRecordChange],
  )

  const move = React.useCallback(
    (id: string, patch: Partial<T>) => change(id, patch, onMove ?? onRecordChange),
    [change, onMove, onRecordChange],
  )

  const create = React.useCallback(
    async (draft: Partial<T>) => {
      const id = typeof draft.id === "string" && draft.id ? draft.id : `tmp_${Math.random().toString(36).slice(2, 8)}`
      const row = { ...draft, id } as T
      setAdded((prev) => [...prev, row])
      try {
        await onCreate?.(row)
      } catch (error) {
        setAdded((prev) => prev.filter((item) => item.id !== id))
        throw error
      }
    },
    [onCreate],
  )

  const remove = React.useCallback(
    async (ids: readonly string[]) => {
      setHidden((prev) => {
        const next = new Set(prev)
        for (const id of ids) next.add(id)
        return next
      })
      try {
        await onDelete?.(ids)
      } catch (error) {
        setHidden((prev) => {
          const next = new Set(prev)
          for (const id of ids) next.delete(id)
          return next
        })
        throw error
      }
    },
    [onDelete],
  )

  return { records: view, update, move, create, remove }
}

import { toCsv, type CsvColumn } from "@/lib/csv"

/**
 * One collection, many views. Pure helpers only: no fetching, no theme.
 * Dates are calendar days (`YYYY-MM-DD`) so a timezone never shifts the day.
 */

export const FIELD_TYPES = [
  "text",
  "number",
  "currency",
  "date",
  "daterange",
  "select",
  "status",
  "person",
  "relation",
  "boolean",
  "url",
  "image",
  "progress",
] as const

export type FieldType = (typeof FIELD_TYPES)[number]

export const FIELD_ICON_NAMES = [
  "text",
  "hash",
  "currency",
  "calendar",
  "user",
  "link",
  "image",
  "check",
  "status",
  "flag",
  "building",
  "progress",
  "tag",
] as const

export type FieldIconName = (typeof FIELD_ICON_NAMES)[number]

export type ChartTone = 1 | 2 | 3 | 4 | 5

export type FieldOption = {
  value: string
  label: string
  tone?: ChartTone
}

export type FieldDef = {
  id: string
  label: string
  type: FieldType
  icon?: FieldIconName
  options?: readonly FieldOption[]
  /** ISO currency code. Default USD. */
  currency?: string
  /** `compact` (default for currency) or `standard`. */
  format?: "compact" | "standard"
  /** Property-panel section. Default Details. */
  section?: string
  readOnly?: boolean
}

export const VIEW_KINDS = [
  "table",
  "kanban",
  "calendar",
  "timeline",
  "grouped-list",
  "gallery",
] as const

export type ViewKind = (typeof VIEW_KINDS)[number]

export type ViewConfig = {
  id: string
  kind: ViewKind
  label: string
  titleField?: string
  subtitleField?: string
  groupField?: string
  sumField?: string
  dateField?: string
  startField?: string
  endField?: string
  coverField?: string
  chipField?: string
  /** Gallery headline. Falls back to the first currency or number field. */
  headlineField?: string
  cardFields?: readonly string[]
  columns?: readonly string[]
}

export type MultiRecord = { id: string } & Record<string, unknown>

export type PersonValue = { name: string; avatarUrl?: string | null }

export type DateRangeValue = { start: string; end: string }

export const FILTER_OPS = [
  "is",
  "isNot",
  "contains",
  "gt",
  "lt",
  "empty",
  "notEmpty",
  "before",
  "after",
] as const

export type FilterOp = (typeof FILTER_OPS)[number]

export type FilterClause = {
  id: string
  field: string
  op: FilterOp
  value?: string
}

export type SortDirection = "asc" | "desc"

export type SortClause = {
  field: string
  direction: SortDirection
}

export type RecordGroup<T> = {
  key: string
  label: string
  records: T[]
  sum: number | null
}

export type CalendarDay = {
  iso: string
  inMonth: boolean
}

export type TimelineZoom = "day" | "week" | "month" | "quarter"

export type TimelineTick = {
  iso: string
  label: string
}

export type DateParts = { y: number; m: number; d: number }

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/
const DAY_MS = 86_400_000

export function isFilterOp(value: string): value is FilterOp {
  return (FILTER_OPS as readonly string[]).includes(value)
}

export function parseDateOnly(value: unknown): DateParts | null {
  if (typeof value !== "string") return null
  const match = DATE_RE.exec(value)
  if (!match) return null
  const y = Number(match[1])
  const m = Number(match[2])
  const d = Number(match[3])
  if (m < 1 || m > 12 || d < 1 || d > 31) return null
  const utc = new Date(Date.UTC(y, m - 1, d))
  if (
    utc.getUTCFullYear() !== y ||
    utc.getUTCMonth() !== m - 1 ||
    utc.getUTCDate() !== d
  ) {
    return null
  }
  return { y, m, d }
}

export function formatDateOnly(parts: DateParts): string {
  const m = String(parts.m).padStart(2, "0")
  const d = String(parts.d).padStart(2, "0")
  return `${String(parts.y).padStart(4, "0")}-${m}-${d}`
}

function dateUtc(parts: DateParts): number {
  return Date.UTC(parts.y, parts.m - 1, parts.d)
}

function fromUtc(ms: number): DateParts {
  const date = new Date(ms)
  return { y: date.getUTCFullYear(), m: date.getUTCMonth() + 1, d: date.getUTCDate() }
}

/** Local calendar day for "today". Pass a Date in tests. */
export function localToday(now = new Date()): string {
  return formatDateOnly({
    y: now.getFullYear(),
    m: now.getMonth() + 1,
    d: now.getDate(),
  })
}

export function addDays(iso: string, days: number): string | null {
  const parts = parseDateOnly(iso)
  if (!parts || !Number.isFinite(days)) return null
  return formatDateOnly(fromUtc(dateUtc(parts) + Math.trunc(days) * DAY_MS))
}

export function diffDays(start: string, end: string): number | null {
  const a = parseDateOnly(start)
  const b = parseDateOnly(end)
  if (!a || !b) return null
  return Math.round((dateUtc(b) - dateUtc(a)) / DAY_MS)
}

export function addMonths(iso: string, months: number): string | null {
  const parts = parseDateOnly(iso)
  if (!parts || !Number.isFinite(months)) return null
  const index = parts.y * 12 + (parts.m - 1) + Math.trunc(months)
  const y = Math.floor(index / 12)
  const m = (index % 12) + 1
  const dim = new Date(Date.UTC(y, m, 0)).getUTCDate()
  return formatDateOnly({ y, m, d: Math.min(parts.d, dim) })
}

export function startOfWeek(iso: string, weekStartsOn = 1): string | null {
  const parts = parseDateOnly(iso)
  if (!parts) return null
  const weekday = new Date(dateUtc(parts)).getUTCDay()
  const lead = (weekday - weekStartsOn + 7) % 7
  return addDays(iso, -lead)
}

export function startOfMonth(iso: string): string | null {
  const parts = parseDateOnly(iso)
  if (!parts) return null
  return formatDateOnly({ y: parts.y, m: parts.m, d: 1 })
}

export function startOfQuarter(iso: string): string | null {
  const parts = parseDateOnly(iso)
  if (!parts) return null
  const m = Math.floor((parts.m - 1) / 3) * 3 + 1
  return formatDateOnly({ y: parts.y, m, d: 1 })
}

export function weekdayIndex(iso: string): number | null {
  const parts = parseDateOnly(iso)
  if (!parts) return null
  return new Date(dateUtc(parts)).getUTCDay()
}

export function asNumber(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value
  if (typeof value === "string" && value.trim() !== "") {
    const n = Number(value)
    if (Number.isFinite(n)) return n
  }
  return null
}

export function asPerson(value: unknown): PersonValue | null {
  if (typeof value === "string" && value.trim()) return { name: value.trim() }
  if (!value || typeof value !== "object") return null
  const name = (value as { name?: unknown }).name
  if (typeof name !== "string" || !name.trim()) return null
  const avatar = (value as { avatarUrl?: unknown }).avatarUrl
  return {
    name: name.trim(),
    avatarUrl: typeof avatar === "string" ? avatar : undefined,
  }
}

export function asDateRange(value: unknown): DateRangeValue | null {
  if (!value || typeof value !== "object") return null
  const start = (value as { start?: unknown }).start
  const end = (value as { end?: unknown }).end
  if (typeof start !== "string" || typeof end !== "string") return null
  if (!parseDateOnly(start) || !parseDateOnly(end)) return null
  return { start, end }
}

export function isEmptyValue(value: unknown): boolean {
  if (value == null) return true
  if (typeof value === "string") return value.trim() === ""
  if (typeof value === "number") return !Number.isFinite(value)
  if (typeof value === "boolean") return false
  if (asPerson(value)) return false
  if (asDateRange(value)) return false
  return false
}

export function foldText(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
}

export function fieldById(
  fields: readonly FieldDef[],
  id: string | undefined,
): FieldDef | undefined {
  if (!id) return undefined
  return fields.find((field) => field.id === id)
}

export function titleFieldOf(
  fields: readonly FieldDef[],
  preferred?: string,
): FieldDef | undefined {
  return fieldById(fields, preferred) ?? fields.find((field) => field.type === "text")
}

export function recordTitle(
  record: MultiRecord,
  fields: readonly FieldDef[],
  preferred?: string,
): string {
  const field = titleFieldOf(fields, preferred)
  if (!field) return record.id
  const text = formatFieldValue(record[field.id], field)
  return text || record.id
}

export function optionLabel(field: FieldDef, value: string): string {
  return field.options?.find((option) => option.value === value)?.label ?? value
}

export function optionTone(field: FieldDef, value: string, index = 0): ChartTone {
  const tone = field.options?.find((option) => option.value === value)?.tone
  if (tone) return tone
  const fallback = (index % 5) + 1
  return fallback as ChartTone
}

export function formatCurrency(
  value: number,
  locale?: string,
  currency = "USD",
  format: "compact" | "standard" = "compact",
): string {
  const compact = format === "compact" && Math.abs(value) >= 1000
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    maximumFractionDigits: compact ? 1 : 2,
    minimumFractionDigits: 0,
  }).format(value)
}

export function formatNumber(value: number, locale?: string): string {
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(value)
}

export function formatDateLabel(iso: string, locale?: string): string {
  const parts = parseDateOnly(iso)
  if (!parts) return ""
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(parts.y, parts.m - 1, parts.d)))
}

export function formatMonthLabel(year: number, monthIndex: number, locale?: string): string {
  return new Intl.DateTimeFormat(locale, {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(year, monthIndex, 1)))
}

export function weekdayLabels(locale: string | undefined, weekStartsOn = 1): string[] {
  const monday = new Date(Date.UTC(2026, 0, 5))
  return Array.from({ length: 7 }, (_, index) => {
    const day = new Date(monday.getTime() + ((index + weekStartsOn + 6) % 7) * DAY_MS)
    return new Intl.DateTimeFormat(locale, { weekday: "short", timeZone: "UTC" }).format(day)
  })
}

export function formatFieldValue(
  value: unknown,
  field: FieldDef,
  locale?: string,
): string {
  if (isEmptyValue(value)) return ""
  switch (field.type) {
    case "number":
      return formatNumber(asNumber(value) ?? 0, locale)
    case "currency":
      return formatCurrency(
        asNumber(value) ?? 0,
        locale,
        field.currency,
        field.format ?? "compact",
      )
    case "progress": {
      const n = asNumber(value) ?? 0
      return `${formatNumber(n, locale)}%`
    }
    case "date":
      return formatDateLabel(String(value), locale)
    case "daterange": {
      const range = asDateRange(value)
      if (!range) return ""
      return `${formatDateLabel(range.start, locale)} – ${formatDateLabel(range.end, locale)}`
    }
    case "select":
    case "status":
      return optionLabel(field, String(value))
    case "person":
    case "relation":
      return asPerson(value)?.name ?? ""
    case "boolean":
      return value === true ? "Yes" : "No"
    default:
      return typeof value === "string" ? value : String(value)
  }
}

export function searchText(
  record: MultiRecord,
  fields: readonly FieldDef[],
  locale?: string,
): string {
  const parts = fields.map((field) => formatFieldValue(record[field.id], field, locale))
  parts.push(record.id)
  return foldText(parts.filter(Boolean).join(" "))
}

export function searchRecords<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  query: string,
  locale?: string,
): T[] {
  const needle = foldText(query.trim())
  if (!needle) return [...records]
  return records.filter((record) => searchText(record, fields, locale).includes(needle))
}

function compareClause(
  record: MultiRecord,
  field: FieldDef,
  clause: FilterClause,
  locale?: string,
): boolean {
  const value = record[field.id]
  const empty = isEmptyValue(value)
  switch (clause.op) {
    case "empty":
      return empty
    case "notEmpty":
      return !empty
    case "contains": {
      if (empty) return false
      const hay = foldText(formatFieldValue(value, field, locale))
      return hay.includes(foldText(clause.value ?? ""))
    }
    case "is":
    case "isNot": {
      const expected = clause.value ?? ""
      let same = false
      if (field.type === "number" || field.type === "currency" || field.type === "progress") {
        same = asNumber(value) === asNumber(expected)
      } else if (field.type === "boolean") {
        same = String(value === true) === expected
      } else if (field.type === "person" || field.type === "relation") {
        same = (asPerson(value)?.name ?? "") === expected
      } else {
        same = String(value ?? "") === expected
      }
      return clause.op === "is" ? same : !same
    }
    case "gt":
    case "lt": {
      const left = asNumber(value)
      const right = asNumber(clause.value)
      if (left == null || right == null) return false
      return clause.op === "gt" ? left > right : left < right
    }
    case "before":
    case "after": {
      const iso = typeof value === "string" ? value : asDateRange(value)?.start
      if (!iso || !clause.value || !parseDateOnly(iso) || !parseDateOnly(clause.value)) return false
      return clause.op === "before" ? iso < clause.value : iso > clause.value
    }
    default:
      return true
  }
}

export function filterRecords<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  filters: readonly FilterClause[],
  locale?: string,
): T[] {
  if (!filters.length) return [...records]
  return records.filter((record) =>
    filters.every((clause) => {
      const field = fieldById(fields, clause.field)
      if (!field) return true
      return compareClause(record, field, clause, locale)
    }),
  )
}

function sortValue(record: MultiRecord, field: FieldDef): string | number | null {
  const value = record[field.id]
  if (isEmptyValue(value)) return null
  if (field.type === "number" || field.type === "currency" || field.type === "progress") {
    return asNumber(value)
  }
  if (field.type === "boolean") return value === true ? 1 : 0
  if (field.type === "date") return typeof value === "string" ? value : null
  if (field.type === "daterange") return asDateRange(value)?.start ?? null
  if (field.type === "person" || field.type === "relation") return asPerson(value)?.name ?? null
  if (field.type === "select" || field.type === "status") return optionLabel(field, String(value))
  return String(value)
}

export function compareFieldValues(
  left: MultiRecord,
  right: MultiRecord,
  field: FieldDef,
  direction: SortDirection,
  locale?: string,
): number {
  const a = sortValue(left, field)
  const b = sortValue(right, field)
  if (a == null && b == null) return 0
  if (a == null) return 1
  if (b == null) return -1
  let result = 0
  if (typeof a === "number" && typeof b === "number") result = a - b
  else result = String(a).localeCompare(String(b), locale, { numeric: true, sensitivity: "base" })
  return direction === "asc" ? result : -result
}

export function sortRecords<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  sort: SortClause | null | undefined,
  locale?: string,
): T[] {
  if (!sort) return [...records]
  const field = fieldById(fields, sort.field)
  if (!field) return [...records]
  return records
    .map((record, index) => ({ record, index }))
    .sort((a, b) => {
      const result = compareFieldValues(a.record, b.record, field, sort.direction, locale)
      return result || a.index - b.index
    })
    .map((entry) => entry.record)
}

export function groupKey(record: MultiRecord, field: FieldDef): string {
  const value = record[field.id]
  if (isEmptyValue(value)) return ""
  if (field.type === "person" || field.type === "relation") return asPerson(value)?.name ?? ""
  if (field.type === "boolean") return value === true ? "true" : "false"
  return String(value)
}

export function groupRecords<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  fieldId: string | null | undefined,
  options?: { includeEmpty?: boolean; emptyLabel?: string; locale?: string },
): RecordGroup<T>[] {
  const field = fieldById(fields, fieldId ?? undefined)
  if (!field) {
    return [{ key: "", label: options?.emptyLabel ?? "All", records: [...records], sum: null }]
  }
  const buckets = new Map<string, T[]>()
  for (const record of records) {
    const key = groupKey(record, field)
    const list = buckets.get(key)
    if (list) list.push(record)
    else buckets.set(key, [record])
  }
  const keys: string[] = []
  if (field.options?.length) {
    for (const option of field.options) keys.push(option.value)
  }
  if (field.type === "boolean") keys.push("true", "false")
  for (const key of buckets.keys()) {
    if (!keys.includes(key)) keys.push(key)
  }
  if (!keys.includes("") && buckets.has("")) keys.push("")

  const emptyLabel = options?.emptyLabel ?? "Empty"
  return keys.filter((key) => options?.includeEmpty || (buckets.get(key)?.length ?? 0) > 0)
    .map((key) => ({
      key,
      label: key === "" ? emptyLabel : labelForGroup(field, key),
      records: buckets.get(key) ?? [],
      sum: null,
    }))
}

function labelForGroup(field: FieldDef, key: string): string {
  if (field.type === "boolean") return key === "true" ? "Yes" : "No"
  if (field.type === "select" || field.type === "status") return optionLabel(field, key)
  return key
}

export function sumField(
  records: readonly MultiRecord[],
  field: FieldDef | undefined,
): number | null {
  if (!field) return null
  let total = 0
  let any = false
  for (const record of records) {
    const n = asNumber(record[field.id])
    if (n == null) continue
    total += n
    any = true
  }
  return any ? total : null
}

export function groupRecordsWithSum<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  fieldId: string | null | undefined,
  sumFieldId: string | undefined,
  options?: { includeEmpty?: boolean; emptyLabel?: string; locale?: string },
): RecordGroup<T>[] {
  const groups = groupRecords(records, fields, fieldId, options)
  const metric = fieldById(fields, sumFieldId)
  return groups.map((group) => ({ ...group, sum: sumField(group.records, metric) }))
}

/** Six weeks, Monday-first unless `weekStartsOn` says otherwise. `monthIndex` is 0–11. */
export function monthGrid(year: number, monthIndex: number, weekStartsOn = 1): CalendarDay[] {
  const first = formatDateOnly({ y: year, m: monthIndex + 1, d: 1 })
  const origin = startOfWeek(first, weekStartsOn) ?? first
  const days: CalendarDay[] = []
  for (let index = 0; index < 42; index += 1) {
    const iso = addDays(origin, index) ?? origin
    const parts = parseDateOnly(iso)
    days.push({
      iso,
      inMonth: Boolean(parts && parts.y === year && parts.m === monthIndex + 1),
    })
  }
  return days
}

export function chunkWeeks(days: readonly CalendarDay[]): CalendarDay[][] {
  const weeks: CalendarDay[][] = []
  for (let index = 0; index < days.length; index += 7) weeks.push(days.slice(index, index + 7))
  return weeks
}

export function shiftIso(iso: string, zoom: TimelineZoom, units: number): string | null {
  if (zoom === "day") return addDays(iso, units)
  if (zoom === "week") return addDays(iso, units * 7)
  if (zoom === "month") return addMonths(iso, units)
  return addMonths(iso, units * 3)
}

export function snapToUnit(iso: string, zoom: TimelineZoom, weekStartsOn = 1): string | null {
  if (!parseDateOnly(iso)) return null
  if (zoom === "day") return iso
  if (zoom === "week") return startOfWeek(iso, weekStartsOn)
  if (zoom === "month") return startOfMonth(iso)
  return startOfQuarter(iso)
}

export function unitsBetween(
  start: string,
  end: string,
  zoom: TimelineZoom,
  weekStartsOn = 1,
): number | null {
  const a = snapToUnit(start, zoom, weekStartsOn)
  const b = snapToUnit(end, zoom, weekStartsOn)
  if (!a || !b) return null
  if (zoom === "day" || zoom === "week") {
    const days = diffDays(a, b)
    if (days == null) return null
    return zoom === "day" ? days : Math.round(days / 7)
  }
  const pa = parseDateOnly(a)
  const pb = parseDateOnly(b)
  if (!pa || !pb) return null
  const months = (pb.y - pa.y) * 12 + (pb.m - pa.m)
  return zoom === "month" ? months : Math.round(months / 3)
}

/** Inclusive range. A same-day bar still occupies one unit. */
export function barPlacement(
  rangeStart: string,
  start: string,
  end: string,
  zoom: TimelineZoom,
  weekStartsOn = 1,
): { offset: number; span: number } | null {
  const offset = unitsBetween(rangeStart, start, zoom, weekStartsOn)
  const raw = unitsBetween(start, end, zoom, weekStartsOn)
  if (offset == null || raw == null) return null
  return { offset, span: Math.max(1, raw + 1) }
}

export function moveRange(
  start: string,
  end: string,
  zoom: TimelineZoom,
  units: number,
): { start: string; end: string } | null {
  const nextStart = shiftIso(start, zoom, units)
  const nextEnd = shiftIso(end, zoom, units)
  if (!nextStart || !nextEnd) return null
  return { start: nextStart, end: nextEnd }
}

export function resizeRange(
  start: string,
  end: string,
  edge: "start" | "end",
  zoom: TimelineZoom,
  units: number,
): { start: string; end: string } | null {
  if (edge === "end") {
    const next = shiftIso(end, zoom, units)
    if (!next) return null
    if ((diffDays(start, next) ?? -1) < 0) return { start, end: start }
    return { start, end: next }
  }
  const next = shiftIso(start, zoom, units)
  if (!next) return null
  if ((diffDays(next, end) ?? -1) < 0) return { start: end, end }
  return { start: next, end }
}

export function timelineRange(
  records: readonly MultiRecord[],
  startField: string,
  endField: string,
  zoom: TimelineZoom,
  today: string,
  weekStartsOn = 1,
): { start: string; end: string } {
  let min = today
  let max = today
  for (const record of records) {
    const start = record[startField]
    const end = record[endField]
    if (typeof start === "string" && parseDateOnly(start) && start < min) min = start
    if (typeof end === "string" && parseDateOnly(end) && end > max) max = end
  }
  const paddedStart = shiftIso(min, zoom, -1) ?? min
  const paddedEnd = shiftIso(max, zoom, 1) ?? max
  return {
    start: snapToUnit(paddedStart, zoom, weekStartsOn) ?? paddedStart,
    end: snapToUnit(paddedEnd, zoom, weekStartsOn) ?? paddedEnd,
  }
}

export function timelineTicks(
  start: string,
  end: string,
  zoom: TimelineZoom,
  locale?: string,
  weekStartsOn = 1,
): TimelineTick[] {
  const ticks: TimelineTick[] = []
  let cursor = snapToUnit(start, zoom, weekStartsOn)
  const limit = 400
  while (cursor && cursor <= end && ticks.length < limit) {
    ticks.push({ iso: cursor, label: tickLabel(cursor, zoom, locale) })
    cursor = shiftIso(cursor, zoom, 1)
  }
  return ticks
}

function tickLabel(iso: string, zoom: TimelineZoom, locale?: string): string {
  const parts = parseDateOnly(iso)
  if (!parts) return iso
  const date = new Date(Date.UTC(parts.y, parts.m - 1, parts.d))
  if (zoom === "day") {
    return new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", timeZone: "UTC" }).format(date)
  }
  if (zoom === "week") {
    return new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", timeZone: "UTC" }).format(date)
  }
  if (zoom === "month") {
    return new Intl.DateTimeFormat(locale, { month: "short", timeZone: "UTC" }).format(date)
  }
  const quarter = Math.floor((parts.m - 1) / 3) + 1
  return `Q${quarter} ${parts.y}`
}

export function recordsToCsv(
  records: readonly MultiRecord[],
  fields: readonly FieldDef[],
  locale?: string,
): string {
  const columns: CsvColumn[] = fields.map((field) => ({ key: field.id, header: field.label }))
  const rows = records.map((record) => {
    const row: Record<string, unknown> = {}
    for (const field of fields) row[field.id] = formatFieldValue(record[field.id], field, locale)
    return row
  })
  return toCsv(rows, columns)
}

export function encodeFilters(filters: readonly FilterClause[]): string {
  return filters
    .map((clause) =>
      [clause.field, clause.op, clause.value ?? ""].map((part) => encodeURIComponent(part)).join("~"),
    )
    .join("|")
}

export function decodeFilters(raw: string | null | undefined): FilterClause[] {
  if (!raw) return []
  const clauses: FilterClause[] = []
  for (const part of raw.split("|")) {
    if (!part) continue
    const [fieldRaw, opRaw, valueRaw = ""] = part.split("~")
    if (!fieldRaw || !opRaw) continue
    const field = decodeURIComponent(fieldRaw)
    const op = decodeURIComponent(opRaw)
    if (!isFilterOp(op)) continue
    clauses.push({
      id: `url-${clauses.length}`,
      field,
      op,
      value: decodeURIComponent(valueRaw),
    })
  }
  return clauses
}

export function encodeSort(sort: SortClause | null | undefined): string | null {
  if (!sort) return null
  return `${sort.field}:${sort.direction}`
}

export function decodeSort(raw: string | null | undefined): SortClause | null {
  if (!raw) return null
  const split = raw.indexOf(":")
  if (split < 1) return null
  const field = raw.slice(0, split)
  const direction = raw.slice(split + 1)
  if (direction !== "asc" && direction !== "desc") return null
  return { field, direction }
}

export function draftFromFormData(
  formData: FormData,
  fields: readonly FieldDef[],
): Record<string, unknown> {
  const draft: Record<string, unknown> = {}
  for (const field of fields) {
    if (field.readOnly) continue
    if (field.type === "boolean") {
      const raw = formData.get(field.id)
      draft[field.id] = raw === "true" || raw === "on"
      continue
    }
    if (field.type === "daterange") {
      const start = formData.get(field.id)
      const end = formData.get(`${field.id}__end`)
      if (typeof start === "string" && start && typeof end === "string" && end) {
        draft[field.id] = { start, end }
      }
      continue
    }
    const raw = formData.get(field.id)
    if (typeof raw !== "string" || raw.trim() === "") continue
    if (field.type === "number" || field.type === "currency" || field.type === "progress") {
      draft[field.id] = Number(raw)
      continue
    }
    draft[field.id] = raw
  }
  return draft
}

export function validateDraft(
  draft: Record<string, unknown>,
  fields: readonly FieldDef[],
  titleField?: string,
): string | null {
  const title = titleFieldOf(fields, titleField)
  if (title && !title.readOnly) {
    const value = draft[title.id]
    if (typeof value !== "string" || !value.trim()) return `${title.label} is required`
  }
  for (const field of fields) {
    if (field.type !== "number" && field.type !== "currency" && field.type !== "progress") continue
    const value = draft[field.id]
    if (value == null || value === "") continue
    if (typeof value === "number" && !Number.isFinite(value)) return `${field.label} must be a number`
    if (typeof value === "string" && value.trim() !== "" && !Number.isFinite(Number(value))) {
      return `${field.label} must be a number`
    }
  }
  return null
}

export function createRecordId(prefix = "rec"): string {
  return `${prefix}_${Math.random().toString(36).slice(2, 10)}`
}

export const VIEW_PERSISTENCE_SCOPES = ["global", "project"] as const

export type ViewPersistenceScope = (typeof VIEW_PERSISTENCE_SCOPES)[number]

/** Storage key for which views are enabled. The id is the collection, not a record. */
export function viewPersistenceKey(scope: ViewPersistenceScope, id: string): string {
  const safe = id.replace(/[^a-zA-Z0-9._-]/g, "")
  return `retana.views.${scope}.${safe || "default"}`
}

/**
 * Keeps enabled view ids inside `allowed`, in that order.
 * An empty result falls back to the previous set, then to the first allowed id.
 */
export function coerceEnabledViews(
  next: readonly string[],
  allowed: readonly string[],
  previous?: readonly string[],
): string[] {
  const allow = new Set(allowed)
  const picked = new Set(next.filter((id) => allow.has(id)))
  const ordered = allowed.filter((id) => picked.has(id))
  if (ordered.length > 0) return ordered
  if (previous) {
    const kept = allowed.filter((id) => previous.includes(id))
    if (kept.length > 0) return kept
  }
  return allowed[0] ? [allowed[0]] : []
}

/** Parses a stored id list. `null` means the value is missing or unreadable. */
export function readEnabledViews(
  raw: string | null | undefined,
  allowed: readonly string[],
): string[] | null {
  if (!raw) return null
  try {
    const parsed = JSON.parse(raw) as unknown
    if (!Array.isArray(parsed) || !parsed.every((id) => typeof id === "string")) return null
    const next = coerceEnabledViews(parsed, allowed)
    return next.length > 0 ? next : null
  } catch {
    return null
  }
}

export type CsvColumn = {
  key: string
  header: string
}

export function escapeCsvCell(value: unknown): string {
  if (value == null) return ""
  let text = String(value)
  // Spreadsheets treat a leading = + - @ tab or line break as a formula.
  if (typeof value === "string" && /^[=+\-@\t\r\n]/.test(text)) text = `'${text}`
  if (/[",\n\r']/.test(text)) return `"${text.replace(/"/g, '""')}"`
  return text
}

export function toCsv(
  rows: readonly Record<string, unknown>[],
  columns: readonly CsvColumn[],
): string {
  const head = columns.map((column) => escapeCsvCell(column.header)).join(",")
  const body = rows
    .map((row) => columns.map((column) => escapeCsvCell(row[column.key])).join(","))
    .join("\n")
  return body ? `${head}\n${body}` : head
}

export function downloadCsv(filename: string, csv: string) {
  if (typeof document === "undefined") return
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" })
  const url = URL.createObjectURL(blob)
  const link = document.createElement("a")
  link.href = url
  link.download = filename.endsWith(".csv") ? filename : `${filename}.csv`
  link.click()
  URL.revokeObjectURL(url)
}

"use client"

import * as React from "react"
import { AnimatePresence, LayoutGroup, motion, useReducedMotion } from "motion/react"
import { Check, Plus } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { motionPresets } from "@/lib/motion"
import { SegmentedControl } from "@/components/ui/segmented-control"

export type ViewOption = {
  id: string
  label: string
  icon?: React.ReactNode
}

export type ViewCustomizerClassNames = {
  content?: string
  tile?: string
  footer?: string
}

export type ViewCustomizerProps = {
  title?: string
  subtitle?: string
  views: readonly ViewOption[]
  enabled: readonly string[]
  onEnabledChange: (ids: string[]) => void
  showAllLabel?: string
  /** At least one view stays enabled. */
  minimumLabel?: string
  footer?: React.ReactNode
  children: React.ReactNode
  className?: string
  classNames?: ViewCustomizerClassNames
}

export function ViewCustomizer({
  title = "Views",
  subtitle,
  views,
  enabled,
  onEnabledChange,
  showAllLabel = "Show all",
  minimumLabel = "At least one view stays on.",
  footer,
  children,
  className,
  classNames,
}: ViewCustomizerProps) {
  const enabledSet = new Set(enabled)
  const allOn = views.length > 0 && views.every((view) => enabledSet.has(view.id))
  const [notice, setNotice] = React.useState("")

  function toggle(id: string) {
    const on = enabledSet.has(id)
    if (on && enabled.length <= 1) {
      setNotice(minimumLabel)
      return
    }
    setNotice("")
    const next = on ? enabled.filter((item) => item !== id) : [...enabled, id]
    onEnabledChange(views.map((view) => view.id).filter((item) => next.includes(item)))
  }

  return (
    <Popover>
      <PopoverTrigger asChild>{children}</PopoverTrigger>
      <PopoverContent
        side="top"
        sideOffset={12}
        className={cn("relative w-80 gap-3 p-3", className, classNames?.content)}
      >
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <h2 className="text-sm font-semibold">{title}</h2>
            {subtitle ? <p className="mt-0.5 text-xs text-muted-foreground wrap-anywhere">{subtitle}</p> : null}
          </div>
          {allOn ? null : (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="shrink-0"
              onClick={() => {
                setNotice("")
                onEnabledChange(views.map((view) => view.id))
              }}
            >
              {showAllLabel}
            </Button>
          )}
        </div>
        <div role="group" aria-label={title} className="grid grid-cols-4 gap-2">
          {views.map((view) => {
            const on = enabledSet.has(view.id)
            return (
              <button
                key={view.id}
                type="button"
                aria-pressed={on}
                className={cn(
                  "relative flex min-h-16 flex-col items-center justify-center gap-1 rounded-lg px-1 py-2 text-xs focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                  on
                    ? "border border-border bg-muted font-semibold text-foreground"
                    : "border border-dashed border-border bg-transparent text-muted-foreground",
                  "hover:bg-accent hover:text-accent-foreground",
                  classNames?.tile,
                )}
                onClick={() => toggle(view.id)}
              >
                {on ? (
                  <span className="absolute -top-1 -end-1 grid size-4 place-items-center rounded-full bg-primary text-primary-foreground">
                    <Check className="size-2.5" aria-hidden />
                  </span>
                ) : null}
                {view.icon ? <span aria-hidden>{view.icon}</span> : null}
                <span className="max-w-full truncate">{view.label}</span>
              </button>
            )
          })}
        </div>
        <p className="sr-only" role="status">
          {notice}
        </p>
        {footer ? <div className={cn("border-t border-border pt-2 text-xs text-muted-foreground", classNames?.footer)}>{footer}</div> : null}
        <span
          aria-hidden
          className="absolute top-full left-1/2 size-2 -translate-x-1/2 -translate-y-1/2 rotate-45 border-r border-b border-border bg-popover"
        />
      </PopoverContent>
    </Popover>
  )
}

export type ViewSwitcherItem = {
  id: string
  label: string
  icon?: React.ReactNode
}

export type ViewSwitcherProps = {
  views: readonly ViewSwitcherItem[]
  value?: string
  onValueChange?: (id: string) => void
  onAdd?: () => void
  addLabel?: string
  label?: string
  /** The views menu, usually the "…" trigger for `ViewCustomizer`. */
  menu?: React.ReactNode
  className?: string
}

export function ViewSwitcher({
  views,
  value,
  onValueChange,
  onAdd,
  addLabel = "Add",
  label = "Views",
  menu,
  className,
}: ViewSwitcherProps) {
  const reduced = useReducedMotion()
  const showPill = views.length >= 2
  const spring = reduced ? { duration: 0 } : motionPresets.spring.snappy
  const selected = value && views.some((view) => view.id === value) ? value : views[0]?.id

  return (
    <LayoutGroup>
      <div data-slot="view-switcher" className={cn("inline-flex items-center gap-1.5", className)}>
        {onAdd ? (
          <motion.div layout="position" transition={spring}>
            <Button
              type="button"
              variant="outline"
              size="icon"
              className="rounded-full"
              aria-label={addLabel}
              onClick={onAdd}
            >
              <Plus />
            </Button>
          </motion.div>
        ) : null}
        <AnimatePresence initial={false}>
          {showPill && selected ? (
            <motion.div
              key="view-switcher-pill"
              data-slot="view-switcher-pill"
              layout
              initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.92 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.92 }}
              transition={spring}
            >
              <SegmentedControl
                label={label}
                iconsOnly
                value={selected}
                onValueChange={onValueChange}
                options={views.map((view) => ({
                  value: view.id,
                  label: view.label,
                  icon: view.icon,
                }))}
                classNames={{
                  track: "rounded-full",
                  option: "rounded-full px-2.5",
                  selection: "rounded-full",
                }}
              />
            </motion.div>
          ) : null}
        </AnimatePresence>
        {menu ? (
          <motion.div layout="position" transition={spring}>
            {menu}
          </motion.div>
        ) : null}
      </div>
    </LayoutGroup>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { LayoutGroup, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type Segment = {
  value: string
  label: string
  accessory?: React.ReactNode
  /** Drawn before the label. With `iconsOnly`, the label stays available to assistive tech. */
  icon?: React.ReactNode
}

export type SegmentedControlClassNames = {
  root?: string
  track?: string
  option?: string
  selection?: string
  label?: string
}

export type SegmentedControlProps = {
  options: Segment[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  label?: string
  onOptionIntent?: (value: string) => void
  /** Hides each label visually and keeps it in the accessible name. */
  iconsOnly?: boolean
  className?: string
  classNames?: SegmentedControlClassNames
}

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  onOptionIntent,
  iconsOnly = false,
  className,
  classNames,
}: SegmentedControlProps) {
  const id = React.useId()
  const reduced = useReducedMotion()
  const track = React.useRef<HTMLDivElement>(null)
  const [internal, setInternal] = React.useState(defaultValue ?? options[0]?.value ?? "")
  const selected = value ?? internal

  React.useLayoutEffect(() => {
    const node = track.current
    if (!node) return
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1)
      node.toggleAttribute("data-fade-end", rest > 1)
    }
    edges()
    node.addEventListener("scroll", edges, { passive: true })
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges)
    observer?.observe(node)
    return () => {
      node.removeEventListener("scroll", edges)
      observer?.disconnect()
    }
  }, [options.length])

  const first = React.useRef(true)
  React.useEffect(() => {
    const node = track.current
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]')
    if (!node || !button || node.scrollWidth <= node.clientWidth) {
      first.current = false
      return
    }
    const room = 20
    const start = button.offsetLeft - room
    const end = button.offsetLeft + button.offsetWidth + room - node.clientWidth
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" })
    first.current = false
  }, [selected, reduced])

  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === selected))

  function change(next: string) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    const last = options.length - 1
    const target =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? selectedIndex === last
          ? 0
          : selectedIndex + 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? selectedIndex === 0
            ? last
            : selectedIndex - 1
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : -1
    if (target < 0 || !options[target]) return
    event.preventDefault()
    change(options[target].value)
    track.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(options[target].value)}"]`)?.focus({ preventScroll: true })
  }

  return (
    <div
      data-slot="segmented-control"
      className={cn("inline-flex min-w-0 max-w-full shrink", className, classNames?.root)}
      role="group"
      aria-label={label}
    >
      <LayoutGroup id={id}>
        <motion.div
          ref={track}
          layoutScroll
          data-slot="segmented-control-track"
          className={cn(
            "flex min-w-0 gap-0.5 overflow-x-auto rounded-lg bg-muted p-0.5 [scrollbar-width:none]",
            classNames?.track,
          )}
        >
          {options.map((option, index) => {
            const pressed = selected === option.value
            return (
              <button
                key={option.value}
                id={`${id}-${option.value}`}
                type="button"
                data-slot="segmented-control-option"
                data-value={option.value}
                className={cn(
                  "relative min-h-8 shrink-0 cursor-pointer rounded-md border-0 bg-transparent px-3 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none aria-pressed:text-foreground",
                  classNames?.option,
                )}
                aria-pressed={pressed}
                tabIndex={index === selectedIndex ? 0 : -1}
                onClick={() => change(option.value)}
                onKeyDown={onKeyDown}
                onPointerEnter={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
                onFocus={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
              >
                {pressed ? (
                  <motion.span
                    data-slot="segmented-control-selection"
                    className={cn("absolute inset-0 z-0 rounded-md border border-border bg-background shadow-sm", classNames?.selection)}
                    layoutId="selection"
                    layoutDependency={selected}
                    transition={reduced ? { duration: 0 } : motionPresets.spring.morph}
                    aria-hidden="true"
                  />
                ) : null}
                <span data-slot="segmented-control-label" className={cn("relative z-10 inline-flex items-center gap-1.5", classNames?.label)}>
                  {option.icon}
                  {iconsOnly ? <span className="sr-only">{option.label}</span> : option.label}
                  {option.accessory}
                </span>
              </button>
            )
          })}
        </motion.div>
      </LayoutGroup>
    </div>
  )
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    exit: [0.7, 0, 0.84, 0] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
